local P = LoreForeverPacks.Begin("LoreForever_Voice_Default_MoreQuests2")
P.transportVersion = 1
P.transport = {}
P.transport["quest:1007"] = {
  hash = "d476df",
  fullHash = "d476df",
  text = "The Ancient Statuette. Talen, an elf camped near the dangerous Zoram Strand in northwestern Ashenvale, seeks recovery of a lost relic. After being ambushed and run aground by vicious naga, he dropped his prized ancient statuette along the surf and needs an adventurer to retrieve it from the ruins. The sunken ruins of Zoram along Ashenvale's northwestern shoreline have long attracted those curious about the ancient night elven past. Talen was navigating the shallows in a small vessel when hostile naga surfaced and tore into him with claw and trident. He managed to scramble ashore with bare provisions to make a hasty camp, but in his desperate sprint for survival, his most precious find was dropped into the sands. The ancient statuette left half-buried on the beach is more than a simple souvenir. Talen considers it the entire justification for braving the monster-infested Zoram Strand. Upon its recovery, he reveals that the drowned city holds centuries of forgotten mysteries, and this delicate carving acts as a vital key to understanding what remains hidden beneath the tides.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1007-025e691725c653ec0ae6/1-0000.mp3", duration = 61.3616327, start = 0},
  },
}
P.transport["quest:1010"] = {
  hash = "983a67",
  fullHash = "983a67",
  text = "Bathran's Hair. Bathran's Hair is an Alliance quest offered by Orendil Broadleaf at Maestra's Post in western Ashenvale. Desperate to treat a mysteriously afflicted night elf child whose illness transcends the physical body, Orendil sends adventurers north to scour the ancient ruins of Bathran's Haunt for a restorative plant renowned for mending ailments of the spirit. At Maestra's Post, just south of the Darkshore border, the night elf herbalist Orendil Broadleaf faces a troubling medical crisis. A young child in Astranaar has fallen grievously ill, exhibiting symptoms that resist ordinary physical remedies. Convinced that the sickness plagues the child's spirit rather than merely the flesh, Orendil seeks Bathran's Hair, an uncommon restorative herb historically gathered amidst the ancient elven ruins to the north.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1010-f460c270e29f00f9a0bb/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["quest:1023"] = {
  hash = "c05f09",
  fullHash = "c05f09",
  text = "Raene's Cleansing. This quest marks the tragic continuation of the search for Teronis, a night elf sentinel sent to Lake Falathim. Upon discovering his remains on the shore, the task shifts to recovering his research journal and retrieving the glowing gem held by local murlocs before reporting the grim news back to Astranaar. Sent to Lake Falathim by Raene Wolfrunner, adventurers discover Teronis dead along the waterside. Rather than a rescue, the mission turns into salvage and investigation. Among his belongings lies an intact journal detailing his assignment and findings regarding the strange disturbances in Ashenvale. Teronis had tracked a rare, luminous stone to the lake, which fell into the possession of the aggressive murlocs infesting the shallows. Recovering both Teronis' journal and pryed-away gem is necessary to carry forward the late scout's original mission.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1023-e25b0937c06b103202c2/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["quest:1024"] = {
  hash = "a43551",
  fullHash = "a43551",
  text = "Raene's Cleansing. This intermediate step in the investigation of Ashenvale's corruption sends Alliance adventurers deep into the sacred groves east of Iris Lake. Entrusted with a recovered Glowing Gem, you must consult the dryad Shael'dryn to learn how to restore Dartol's ancient rod. Following the tragic death of the sentinel Teronis, Raene Wolfrunner examines the field notes he left behind. His research indicates that investigating Ashenvale's troubled furbolgs may require an ancient artifact: a rod crafted long ago by a night elf named Dartol. With only a Glowing Gem in hand, Raene admits her tactical expertise as a huntress is ill-suited to deciphering lost arcane and natural mysteries. Rather than guessing at the remaining pieces of Dartol's Rod, Raene directs travelers northeast toward Iris Lake. Tucked away beside a tranquil moonwell dwells Shael'dryn, a dryad whose natural communion with the forest grants her deep insight into ancient relics. By delivering the gem to her, adventurers hope to uncover the missing components and learn how to reforge the rod.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1024-7b77c97c14eb54940f19/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["quest:104"] = {
  hash = "9f569a",
  fullHash = "9f569a",
  text = "The Coastal Menace. Captain Grayson's restless ghost watches the rocky coast of Westfall, haunted by the memory of the shipwreck that took his life and the slaughter of the lighthouse keeper's family. He charges travelers with hunting down the vicious murloc chieftain responsible: Old Murk-Eye. Slaying the beast brings a measure of justice to the shore and helps safeguard future sailors. The Westfall Lighthouse stands as the lone guide through the jagged shallows of the southern coast, but its flame has flickered through bloody tragedies. Captain Grayson lost his life when his vessel broke against the rocks in the dark, an accident precipitated when murlocs terrified the lighthouse keeper's family into fleeing their post. Though the family later returned and relit the flame, the reprieve was brief. The shoreline remained stalked by a particularly cunning and ruthless predator. Old Murk-Eye is not merely another wild beast prowling the tide pools. Grayson recounts watching the creature sway the weaker-minded murlocs along the coast, rallying them into a coordinated strike against the lighthouse. The second raid proved fatal, wiping out the keeper's family before Grayson's helpless spectral eyes. To bring peace to the dead and preserve what remains of safety on the Great Sea, the ghostly captain demands Murk-Eye's death and a scale as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_104-ebec8405695a7d3ce032/1-0000.mp3", duration = 72.6465306, start = 0},
  },
}
P.transport["quest:1060"] = {
  hash = "ca514f",
  fullHash = "ca514f",
  text = "Letter to Jin'Zil. Letter to Jin'Zil is a Horde delivery quest entrusted to adventurers who have slain Serena Bloodfeather in the northern Barrens. Orc rogue Darsok Swiftdagger sends you across the border into the rugged crags of Stonetalon Mountains to deliver word of the harpy matriarch's demise to his old friend, Witch Doctor Jin'Zil. After the harpy threat around the northern Barrens is systematically dismantled, Darsok Swiftdagger reveals that the winged raiders were never native to the scrublands. The Witchwing and Bloodfeather broods descended from the rugged ridges of the Stonetalon Mountains to the northwest. Impressed by your prowess in dispatching Serena Bloodfeather, Darsok sends you into those dangerous peaks to carry news of her death to an old acquaintance, Witch Doctor Jin'Zil, residing at the troll settlement of Malaka'jin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1060-e18e6ff002ea9199d859/1-0000.mp3", duration = 47.0465306, start = 0},
  },
}
P.transport["quest:1069"] = {
  hash = "b62211",
  fullHash = "b62211",
  text = "Deepmoss Spider Eggs. Mebok Mizzyrix in Ratchet aims to capitalize on an exotic culinary craze sweeping Booty Bay: spider egg omelettes. To supply the lucrative overseas market, he hires adventurers to venture into the Stonetalon Mountains and harvest fresh clutches of deepmoss spider eggs. Booty Bay's high rollers and eccentric pirates have developed an insatiable appetite for spider egg omelettes, sparking high demand for rare ingredients across the Great Sea. Recognizing an easy fortune, Ratchet merchant Mebok Mizzyrix has jumped at the chance to supply the southern port. Because the Eastern Kingdoms lack this particular arachnid delicacies, Kalimdor's rugged wilderness provides the perfect supply chain. The harvest requires trekking into the Stonetalon Mountains to find deepmoss spiders. Clutches of their eggs can be discovered clinging beneath the surviving timber of the Venture Company's logging operations in Windshear Crag, or deeper within the web-strewn depths of Sishir Canyon. Gathering the eggs means risking venomous bites and confronting dense infestations that make even seasoned scavengers squeamish. Speed and logistics are critical when moving raw arachnid eggs across the sea before they spoil or hatch. Mebok coordinates closely with Ratchet's Wharfmaster Dizzywig, arranging freight passage on goblin merchant ships bound straight for the docks of Stranglethorn Vale. With the eggs safely packed in crates, Mebok turns a tidy profit on high-seas gastronomy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1069-99799ae1098c9699514f/1-0000.mp3", duration = 85.1069388, start = 0},
  },
}
P.transport["quest:1070"] = {
  hash = "09435d",
  fullHash = "09435d",
  text = "On Guard in Stonetalon. On Guard in Stonetalon is an Alliance breadcrumb quest directing adventurers south from Ashenvale into the rugged Stonetalon Mountains. Sentinel Thenysil dispatches travelers to check on her scout friend, Kaela Shadowspear, who was sent into the crags alongside a gnome mage to monitor industrial incursions by the Venture Company. Stationed in Astranaar, Sentinel Thenysil keeps a close watch on threats pressing toward the ancient forest. Deeply concerned for her friend Kaela Shadowspear, Thenysil asks passing Alliance champions to track her down. Kaela was dispatched into the Stonetalon Mountains by Sentinel Wolfrunner to survey rising turmoil in the heights, but communication has fallen silent, leaving Thenysil anxious for her safety. Thenysil's concern is heightened by Kaela's assigned companion: a gnome mage deployed alongside her by the Alliance leadership. While the night elves have joined the Grand Alliance out of strategic necessity, many Sentinels remain deeply skeptical of arcane practitioners and tinkering gnomes operating in pristine wilderness. Finding Kaela perched on the bluffs above Windshear Crag reveals an outpost keeping vigil over widespread environmental devastation wrought by the Venture Company.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1070-1df500be4ea435c43964/1-0000.mp3", duration = 71.6538776, start = 0},
  },
}
P.transport["quest:1071"] = {
  hash = "94e134",
  fullHash = "94e134",
  text = "A Gnome's Respite. A Gnome's Respite is an Alliance quest offered by the eccentric tinkerer Gaxim Rustfizzle in the Stonetalon Mountains. Overwhelmed by the Venture Company's rapid industrial push into Windshear Crag, Gaxim hires adventurers to cull their loggers and deforesters so he can buy enough breathing room to invent new deterrents. Gaxim Rustfizzle represents the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Stationed among the ancient groves of Stonetalon, his stated duty is proving to the nature-worshipping night elves that modern gnomish invention—blending magic, chemical brews, and mechanics—can actively protect their threatened lands. However, the relentless pace of the Venture Company has left him with barely any time to prototype his defensive devices. To stem the tide, Gaxim sends adventurers directly into the smoking operations at Windshear Crag. By targeting the frontline Venture Co. Loggers and Deforesters, travelers give Gaxim the respite he needs to organize his workshop and devise his next line of defense: strategic, controlled high explosives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1071-d9cab6419a7bad4a0b0f/1-0000.mp3", duration = 62.9289796, start = 0},
  },
}
P.transport["quest:1072"] = {
  hash = "26274b",
  fullHash = "26274b",
  text = "An Old Colleague. An Old Colleague is an Alliance quest given by the gnome engineer Gaxim Rustfizzle in the Stonetalon Mountains. Looking to construct an extraordinarily potent device, Gaxim sends an adventurer all the way across the sea to Ironforge to track down an old acquaintance capable of synthesizing a hazardous explosive concoction. Completing this errand opens the door to procuring the volatile chemical compound known as Nitromirglyceronium. While stationed among the peaks of Stonetalon, Gaxim Rustfizzle conceives of his most ambitious engineering endeavor yet. Creating a mechanism of that scale requires specialized fuel far beyond typical gunpowder or crude oil. Specifically, Gaxim requires Nitromirglyceronium, also designated as NG-5, an explosive mix potent enough to guarantee destructive results should everything go according to plan. Formulating NG-5 is no simple task, and Gaxim knows of only one mind skilled enough to refine it: an old acquaintance named Lomac Gearstrip. Lomac resides far to the east in the gnome quarter of Tinker Town, tucked deep within the mountain stronghold of Ironforge. Entrusted with the long journey, the courier arrives only to be greeted by Lomac's immediate suspicion and paranoid questioning.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1072-eaee4fb75c5681e335ba/1-0000.mp3", duration = 74.3183673, start = 0},
  },
}
P.transport["quest:1073"] = {
  hash = "0f6612",
  fullHash = "0f6612",
  text = "Ineptitude + Chemicals = Fun. Seeking an explosive countermeasure against the Venture Company in the Stonetalon Mountains, Alliance adventurers are sent across the sea to Ironforge. There, the eccentric gnome Lomac Gearstrip agrees to brew his volatile invention, Nitromirglyceronium, provided you fetch the necessary alchemical reagents. Gaxim Rustfizzle, stationed high in the craggy passes of the Stonetalon Mountains, needed potent explosives for the most advanced device he had yet devised against the Venture Company. For that, he turned to an eccentric former colleague living in Ironforge: Lomac Gearstrip. Lomac is the creator of Nitromirglyceronium, a substance so inherently unstable and destructive that he finds the prospect of anyone using it hilarious, regardless of who gets blown apart in the process. Despite Lomac's eagerness to see goblin machinery—and possibly the adventurer—blown into pieces, his workshop in Ironforge is entirely out of the finished compound. Before he will brew a fresh batch of Nitromirglyceronium, Lomac demands common alchemical draughts: Minor Mana Potions and Elixirs of Minor Fortitude. In his eyes, forcing an adventurer to gather these ingredients serves a dual purpose, ensuring he has the raw reagents needed for the reaction while proving they possess at least a shred of respect for the craft of alchemy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1073-37f07aa5f3edb7d74d85/1-0000.mp3", duration = 78.08, start = 0},
  },
}
P.transport["quest:1074"] = {
  hash = "71bb04",
  fullHash = "71bb04",
  text = "Ineptitude + Chemicals = Fun. This errand delivers a canister of volatile NG-5 from the tinker Lomac Gearstrip to Gaxim Rustfizzle in the Stonetalon Mountains. Gaxim requires this unstable chemical to create a potent igniter for several wagons packed with dynamite. The resulting blast forms a critical distraction for Alliance operations in the disputed crags. Gnomish engineering often balances brilliance on the razor edge of catastrophe, and Nitromirglyceronium—or NG-5—is no exception. Lomac Gearstrip hands over the unstable compound with a stern warning: handle it with extreme care, or risk blowing yourself to pieces on the road back to Gaxim Rustfizzle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1074-473b58098ec8728faf59/1-0000.mp3", duration = 38.0865306, start = 0},
  },
}
P.transport["quest:1075"] = {
  hash = "444b5b",
  fullHash = "444b5b",
  text = "A Scroll from Mauren. \"A Scroll from Mauren\" is an Alliance errand carrying word between gnome ingenuity and human arcane craft. The inventive Gaxim Rustfizzle requires a specialized spell to remotely trigger his volatile NG-5 explosives, dispatching couriers to consult with mage Collin Mauren in the heart of Stormwind. Gnomish engineering is legendary for ambitious concepts, but safe execution often requires clever solutions. When Gaxim Rustfizzle set out to design an explosive payload capable of remote activation, mechanical fuses proved insufficient. Rather than relying purely on mechanical timers or trailing cords, Gaxim envisioned a device that would detonate the NG-5 explosives at the push of a single button from a safe vantage point. To bridge the gap between volatile powder and instantaneous trigger, he turned his sights toward arcane magic. To acquire the necessary spellwork, Gaxim directs travelers across the kingdom to Stormwind's bustling Mage Quarter. There resides Collin Mauren, a human spellcaster whose practical understanding of the arcane makes him an ideal partner for ambitious tinkers. Mauren ponders the delicate problem of binding explosive ignition to a distant command, marking the first step in assembling the arcane incantation required to arm Gaxim's hazardous project.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1075-f190e20226d5bb03c3b9/1-0000.mp3", duration = 75.52, start = 0},
  },
}
P.transport["quest:1076"] = {
  hash = "af3960",
  fullHash = "af3960",
  text = "Devils in Westfall. \"Devils in Westfall\" is an Alliance errand undertaken for Collin Mauren in the Mage Quarter of Stormwind. Tasked with aiding an eccentric experiment by the gnome inventor Gaxim Rustfizzle, adventurers are sent into the desolate plains of Westfall to gather volatile debris from living dust devils. The collected dust provides the raw magical component needed to enchant a specialized messaging scroll. The wizard Collin Mauren is assisting the tinkerer Gaxim Rustfizzle with an unusual venture, but arcane work requires specialized reagents. To enchant a scroll capable of carrying Gaxim's desired messaging spell, Mauren cannot rely on simple ink and vellum alone. The swirling elemental magic trapped within Westfall's native dust devils provides the exact volatile medium needed to bind the spell into parchment form. Westfall was once the fertile breadbasket of Stormwind, but drought, banditry, and neglect have left the land arid and wild. Swirling dust devils now roam the untamed fields, posing a hazard to travelers and lone homesteaders alike. By defeating one of these living whirlwinds and gathering its residue, adventurers retrieve the focused elemental essence required to bring the mage's enchantment to life.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1076-7adc508e2f821c429f14/1-0000.mp3", duration = 72.8816327, start = 0},
  },
}
P.transport["quest:1077"] = {
  hash = "9fe524",
  fullHash = "9fe524",
  text = "Special Delivery for Gaxim. Special Delivery for Gaxim represents the return leg of an Alliance courier mission between Stormwind City and the wilds of Kalimdor. Collin Mauren provides a specialized Scroll of Messaging to take back to the gnome tinkerer Gaxim Rustfizzle in the Stonetalon Mountains. The scroll contains the arcane component needed to construct a remote explosive against local deforestation efforts. Gaxim Rustfizzle's efforts to sabotage the destructive operations of the Venture Company require unconventional solutions. Having concocted an explosive compound called NG-5, the tinkerer found himself lacking a reliable means of remote detonation. Rather than turning to crude fuses, Gaxim enlisted help across the Great Sea, reaching out to Collin Mauren in the Mage Quarter of Stormwind to acquire an enchanted Scroll of Messaging.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1077-b7c88d3b23863d8988d4/1-0000.mp3", duration = 46.8114286, start = 0},
  },
}
P.transport["quest:1085"] = {
  hash = "0ca85a",
  fullHash = "0ca85a",
  text = "On Guard in Stonetalon. On Guard in Stonetalon directs Alliance travelers from Kaela Shadowspear to Gaxim Rustfizzle at their camp near Windshear Crag. Facing rampant despoilment by the Venture Company, an otherwise unlikely pair—a cautious night elf sentinel and an eccentric gnome tinkerer—join forces to safeguard the mountain pass. Night elves and gnomes rarely share common ground, especially when it comes to technology and the natural world. In the crags of Stonetalon Mountains, however, necessity bridges the cultural gulf. With the rapacious Venture Company carving out the wilderness and felling ancient trees, the sentinel Kaela Shadowspear has recognized that pure martial prowess alone cannot overcome industrialized pillaging. Welcoming gnome ingenuity into sacred Kaldorei territory demonstrates just how precarious the situation has become. Gaxim Rustfizzle represents the eccentric pragmatism of the Alliance's smaller allies. While night elf society famously turned its back on arcane excess millennia ago, Gaxim believes that abstaining from magic and technical innovation leaves them vulnerable. By pairing alchemy and engineering with a touch of arcane discipline, Gaxim aims to convince his Kaldorei hosts that practical science can defend nature just as effectively as bow and glaive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1085-27c1031fca4f896d62c8/1-0000.mp3", duration = 75.8857143, start = 0},
  },
}
P.transport["quest:1093"] = {
  hash = "1a188a",
  fullHash = "1a188a",
  text = "Super Reaper 6000. Super Reaper 6000 is a quest offered by the disgruntled goblin tinkerer Ziz Fizziks in the Windshear Crag of the Stonetalon Mountains. Looking to curry favor with his new boss Sputtervalve, Ziz hires adventurers to infiltrate the local Venture Company logging operation and steal the schematic blueprints for a colossal woodcutting machine designed by his rival, the gnome Gerenzo Wrenchwhistle. The Venture Trading Company has carved an industrial scar straight into the heart of the Stonetalon Mountains, ruthlessly deforesting Windshear Crag. Yet beneath the smog and spinning blades lies petty corporate rivalry. Ziz Fizziks, a goblin engineer recently cast out of the Venture Company's ranks, has found employment with Sputtervalve. Eager to cement his position and show off his value, Ziz seeks to procure the Venture Company's most prized mechanical asset: the blueprints for their massive automated lumber engine, the Super Reaper 6000.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1093-490c199d194f90b7104a/1-0000.mp3", duration = 55.5102041, start = 0},
  },
}
P.transport["quest:1094"] = {
  hash = "30b6d5",
  fullHash = "30b6d5",
  text = "Further Instructions. Further Instructions is a delivery task connecting the chaotic logging operations of the Stonetalon Mountains to the trade hub of Ratchet. The disgruntled tinkerer Ziz Fizziks sends a courier with stolen blueprints and internal documents to his counterpart, Sputtervalve, aiming to turn corporate espionage into personal advantage. When Ziz Fizziks was booted out of the Venture Company's logging operations in the Windshear Crag, he did not leave empty-handed. Bitter over his dismissal, Fizziks snatched up an assortment of sensitive documents, internal manuals, and technical schematics, culminating in the prized blueprints for the experimental Super Reaper 6000. Desperate to find a buyer or ally willing to exploit the data, he sealed the gathered secrets into an envelope marked for Ratchet. The recipient of the stolen documents is Sputtervalve, an engineer stationed within the neutral port of Ratchet in the Barrens. While Sputtervalve harbors little personal affection or trust for Fizziks, the rivalry with the Venture Company makes the offering impossible to refuse. The Steamwheedle-aligned goblins are constantly looking for ways to diminish their ruthless competitor's footprint while happily reverse-engineering any superior mechanical innovations they stumble across.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1094-4192665b6e4a8ce01b28/1-0000.mp3", duration = 69.355102, start = 0},
  },
}
P.transport["quest:1133"] = {
  hash = "136181",
  fullHash = "136181",
  text = "Journey to Astranaar. Journey to Astranaar is an introductory Alliance quest guiding newcomers arriving on the Kalimdor coast to the inland heart of Ashenvale. Directed by Fiora Longears at Theramore, travelers make their way north toward Ashenvale to report to Shindrell Swiftfire in Astranaar. It marks an adventurer's entry into the growing conflicts surrounding the night elves' ancestral forest. Alliance travelers arriving in Dustwallow Marsh aboard the ferry from Menethil Harbor often look for purpose in northern Kalimdor. At Theramore, Fiora Longears directs capable hands to move deeper inland toward Astranaar, the main night elven settlement within Ashenvale. The journey follows winding paths under ancient, shadowed canopies, leading straight into a forest strained by war and unrest. Curiously, Fiora tells travelers not to bother mentioning her name when arriving in Astranaar, stating plainly that Shindrell Swiftfire does not know her. Her role is simply to funnel fresh Alliance talent where it is needed most. Upon arriving, Shindrell readily welcomes any able-bodied defender, acknowledging that while Ashenvale remains breathtaking, it is no longer the peaceful sanctuary it once was.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1133-592580d109129f577353/1-0000.mp3", duration = 68.5453061, start = 0},
  },
}
P.transport["quest:1134"] = {
  hash = "1022e2",
  fullHash = "1022e2",
  text = "Pridewings of Stonetalon. Shindrell reports an unconfirmed claim: Concerned about covert Horde attacks, the Sentinels in Astranaar seek to intercept a deadly weapon before it can strike their people. Intelligence from Theramore reveals that orc assassins harvest toxic venom from the wyverns of Stonetalon Mountains for clandestine raids. To protect their fragile border, Alliance scouts are dispatched south to harvest the venom sacs first and starve the enemy of their lethal poison. Though open war has not been declared between the Alliance and the Horde across northern Kalimdor, the peace between them is razor-thin. Skirmishes break out under thick forest canopies, and quiet, deniable strikes have replaced full-scale armies. Sentinel commanders in Astranaar maintain constant vigilance against covert enemy movements, knowing that complacency could cost them their sanctuary. Shindrell reports an unconfirmed claim: Intelligence passed from secretive contacts in Theramore brought word of a sinister enterprise underway in the crags of Stonetalon. Orcish stalkers have been gathering venom from wild pridewings around Mirkfallon Lake, using the potent biological agent to coat their blades for fatal ambush raids against Alliance personnel. To blunt the threat, Shindrell Swiftfire directs champions to cull the beasts and seize the venom sacs before Horde agents can harvest them. Ordering the destruction of native beasts weighs heavily on the night elves, who hold deep reverence for Kalimdor's wilderness. Shindrell herself laments that innocent creatures must suffer for a war they have no role in choosing. Yet in the grim calculus of border defense, denying an enemy lethal arms takes precedence over ecological preservation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1134-8e1259cae34871afb780/1-0000.mp3", duration = 97.8285714, start = 0},
  },
}
P.transport["quest:124"] = {
  hash = "cc2b60",
  fullHash = "cc2b60",
  text = "A Baying of Gnolls. Verner Osgood, the stable master in Lakeshire, finds his business under siege by gnolls raiding south from the Redridge foothills. Already strained by Blackrock orc incursions, he asks travelers to clear out the brutes and mystics threatening his livestock. Running a stable in Lakeshire has become increasingly hazardous. Blackrock orcs command the heights of the region, while packs of gnolls roam the surrounding ridges. For Verner Osgood, the situation reached a breaking point when aggressive gnoll raiding bands crept close to the northern borders of his paddocks, preying on any horses that wandered too close to the bluffs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_124-c0a622f8dcc0ae5caa75/1-0000.mp3", duration = 35.5265306, start = 0},
  },
}
P.transport["quest:126"] = {
  hash = "f2ed0d",
  fullHash = "f2ed0d",
  text = "Howling in the Hills. Howling in the Hills is an Alliance bounty offered by Verner Osgood in Lakeshire to hunt down Yowler, the fearsome alpha leading the Redridge gnolls. With Stormwind's military stretched too thin fighting the Blackrock orcs to defend the local borders, Lakeshire relies on visiting adventurers to break the gnoll pack's command. Even after culling the lesser gnolls raiding the paths around Lakeshire, their ominous calls continue to echo through the Redridge ridges. Verner Osgood, Lakeshire's hardworking farrier, recognizes that killing scouts and scavengers will never stem the tide as long as their pack leader remains alive. Rising above the rabble is Yowler, an exceptionally cunning and massive gnoll whose calls direct the pack across the hills. Verner tasks adventurers with hunting down the beast and severing his paw to ensure the howling is silenced once and for all. This contract highlights the grim reality facing the eastern borders of the kingdom of Stormwind. With the missing King Varian Wrynn and regency disputes paralyzing high command, royal soldiers are focused almost exclusively on the entrenched Blackrock orc clans in the north. Everyday settlements like Lakeshire are left completely undefended against native menaces like gnolls, forcing townsfolk like Verner Osgood to organize their own bounties to prevent their homes from being overrun.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_126-19451241123922dcc87b/1-0000.mp3", duration = 75.0497959, start = 0},
  },
}
P.transport["quest:127"] = {
  hash = "01bafc",
  fullHash = "01bafc",
  text = "Selling Fish. Dockmaster Baren manages the bustling pier at Lakeshire, but finding fresh stock for his trade has grown difficult. He pays travelers to haul in spotted sunfish, a prized local staple of Lake Everstill that has become dangerous to gather due to the encroaching murlocs. Lake Everstill is known throughout the surrounding lands for its spotted sunfish, a delicate catch that remains in perpetual demand among the townspeople and passing merchants. Yet despite the abundance beneath the lake's surface, the town's supplies regularly run thin. With Lakeshire stretched to its limits under various local threats, even basic commerce requires the help of freelance adventurers. Normally, local anglers would have little trouble satisfying Dockmaster Baren's orders. However, the rise of aggressive murloc tribes along the shallows and banks has driven ordinary townsfolk away from the water. Travelers looking to fulfill Baren's request must either cast their own lines while watching their backs, or claim the catch directly from the foraging murlocs that plague the shores.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_127-0233d541d49aa94ba771/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["quest:1472"] = {
  hash = "c6ca30",
  fullHash = "c6ca30",
  text = "Devourer of Souls. Devourer of Souls is an introductory step in a Forsaken warlock's journey to summon and bind a succubus. Directed by Carendin Halgar in the Undercity's Temple of the Damned, the practitioner must confer with his assistant, Godrick Farsan, to learn how to lure such a creature from the Twisting Nether. The ritual demands an irresistible stimulus: the hearts of pure and loving mortals. Carendin Halgar teaches that a succubus cannot simply be pulled across the threshold on command; it must be enticed. Driven by an insatiable hunger to ruin virtue and consume mortal essence, the demon requires a specific lure. The warlock's strategy relies on exploiting this singular desire by offering up the hearts of genuinely virtuous, loving men as bait. Halgar directs his acolytes to Godrick Farsan, who knows where such rare quarry can be harvested. Located deeper within the Temple of the Damned, Godrick Farsan assists Carendin with the practical preparations of demonic binding. Though Farsan has lost his physical eyesight, he claims his condition grants him a profound second sight—allowing him to perceive underlying spiritual currents and far-off souls with uncanny clarity. He serves as the guide for locating the pure hearts necessary to draw the demon forth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1472-a62d424bd97584af8fbb/1-0000.mp3", duration = 73.9265306, start = 0},
  },
}
P.transport["quest:1474"] = {
  hash = "caffed",
  fullHash = "caffed",
  text = "The Binding. The Binding is the final initiation in an Undercity warlock's journey to summon and command a succubus. Directed by Carendin Halgar, the practitioner uses pure hearts to draw a demon from the Twisting Nether into a ritual circle, subjugating its will through combat. Within the dark alcoves of the Magic Quarter, Forsaken warlocks refine their command over demonic entities. Summoning a succubus is considered a critical rite of passage. Unlike the brute force of a voidwalker or the minor malice of an imp, a succubus wields seductive and mental enchantments capable of ensnaring the caster. Carendin Halgar requires initiates to prove their mind and magic are ironclad before trusting them with permanent dominion over such an entity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1474-bbbb2f253e0f2035de37/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["quest:1476"] = {
  hash = "c44d97",
  fullHash = "c44d97",
  text = "Hearts of the Pure. Hearts of the Pure is a sinister warlock trial assigned in the Undercity by Godrick Farsan on behalf of Carendin Halgar. In order to prepare the ritual bait needed to bind a succubus, an aspiring summoner must hunt down and butcher two uniquely righteous human men. Their pure hearts serve as an irresistible temptation for the demonic temptress awaiting summoning. Binding a succubus requires an understanding of temptation that cuts both ways. While the Nether's sirens prey upon desire and ruin, nothing draws them out of the Twisting Nether quite like untainted virtue ripe for corruption. Within the Temple of the Damned, master summoner Carendin Halgar delegates the groundwork to Godrick Farsan, who scours human lands for souls whose goodness remains pristine and unbroken. Farsan identifies two distinct paragons of virtue. The first is Dalin Forgewright, an honorable man attending to desperate Lordaeron refugees barred from sanctuary outside the sealed Greymane Wall in southern Silverpine. The second is Comar Villard, a faithful husband tirelessly searching the perilous marshlands of the Wetlands for any trace of his lost wife. To a Forsaken warlock, their devotion, empathy, and loyalty make them prime sacrifices.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1476-685774847f23cb86b325/1-0000.mp3", duration = 71.3665306, start = 0},
  },
}
P.transport["quest:1483"] = {
  hash = "1e9ecb",
  fullHash = "1e9ecb",
  text = "Ziz Fizziks. This quest sends travelers from Ratchet to check on Ziz Fizziks, a disgruntled goblin engineer stationed on the western ridge of Windshear Crag. Offended when the Venture Company hired a gnome engineer over him, Ziz defected to the Tinkers' Union under Sputtervalve's demanding direction. The Venture Company relies on ruthless exploitation and mechanical innovation, but it crossed a line for Ziz Fizziks when it brought on a gnome engineer named Gerenzo Wrenchwhistle. Deeply insulted by having to work alongside a gnomish rival, Ziz immediately sought a way out. He reached out to Sputtervalve, a contact representing the Tinkers' Union, begging for a transfer away from Gerenzo's oversight. Securing a new position with the Tinkers' Union did not grant Ziz the easy life he anticipated. Stationed on the western edge of Windshear Crag, he quickly discovered that Sputtervalve is just as much of a slave driver as any Venture Company foreman. Even so, Ziz considers heavy labor under a demanding goblin superior far preferable to sharing an engineering workshop with a gnome.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1483-bf8b14a07c50ae779f49/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["quest:150"] = {
  hash = "643dde",
  fullHash = "643dde",
  text = "Murloc Poachers. Dockmaster Baren of Lakeshire needs adventurers to thin the swelling ranks of murlocs along Lake Everstill before they deplete the town's primary food source. What begins as a practical pest-control bounty raises an unsettling ecological question: why are coastal creatures settling so deep into the inland mountains? Lake Everstill is the lifeblood of Lakeshire, keeping the mountain town fed and supplying its market with fresh catches. When large tribes of murlocs began dropping anchor along the shallows, Dockmaster Baren realized the town faced an ecological crisis. The ravenous fish-men were aggressively scouring the waters, threatening to wipe out the local fish populations entirely if left unchecked. Murlocs are typically coastal scavengers, making their massive presence high up in the Redridge Mountains an unusual sight. Dockmaster Baren openly wonders why they have traveled so far from the open ocean. Whether driven inland by maritime predators, fleeing territorial squabbles, or drawn by Lake Everstill's bountiful waters, their displacement hints at deeper disruptions elsewhere in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_150-764f700caabf4c8482cb/1-0000.mp3", duration = 63.5036735, start = 0},
  },
}
P.transport["quest:1507"] = {
  hash = "8b04d3",
  fullHash = "8b04d3",
  text = "Devourer of Souls. Devourer of Souls is the opening task in an aspiring Horde warlock's journey to summon and command a succubus. Offered by Gan'rul Bloodeye deep within the Cleft of Shadow, the quest sends the practitioner across the cavern to consult the ancient warlock Cazul on how to lure and bind such a manipulative demon. Warlocks of the Horde who have mastered lesser demons like the imp and the voidwalker eventually reach a point where brute force is no longer enough. Gan'rul Bloodeye, overseer of dark arts beneath Orgrimmar, judges when a warlock is ready to reach into the Twisting Nether for a succubus—a creature notorious for turning the minds of the frail against themselves. Binding such a fiend requires subtle methods rather than sheer strength. Because a succubus preys on mortal desires, it cannot be summoned by raw incantations alone; it must be baited into our world with an object imbued with pure love and devotion. Unwilling or unable to provide such a relic himself, Gan'rul directs the summoner to Cazul, an ancient warlock lurking within the Cleft of Shadow whose extensive knowledge of the arcane and demonic rites guides the next phase of the ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1507-4d5e2828cd0f5a7ef393/1-0000.mp3", duration = 65.9853061, start = 0},
  },
}
P.transport["quest:1508"] = {
  hash = "388f32",
  fullHash = "388f32",
  text = "Blind Cazul. Blind Cazul is a transitional step in the Horde warlock trial to bind a succubus. After being directed by the coven leaders in the Cleft of Shadow, an initiate seeks out the sightless warlock Cazul, who points toward an object of intense emotion needed for the ritual. Subjugating a demonic minion requires more than raw willpower; certain creatures of the Twisting Nether must be drawn across the veil by their innate cravings. A succubus, known as a devourer of souls, responds eagerly to mortal longing, sorrow, and unfulfilled desire. Cazul understands this well, recognizing immediately why an aspiring summoner has sought him out. Despite his physical blindness, Cazul remains sharply attuned to the quiet lives and tragedies unfolding within Orgrimmar's red ramparts. Rather than sending the warlock directly to battle, he directs them to an orc woman named Zankaja living atop the bluffs near the wind rider roost. Zankaja has been anxiously waiting for the return of her mate, Dogran, harboring the very despair that demons find irresistible.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1508-c6b8452a13ad6456ca55/1-0000.mp3", duration = 61.675102, start = 0},
  },
}
P.transport["quest:1509"] = {
  hash = "a1b4d9",
  fullHash = "a1b4d9",
  text = "News of Dogran. This quest sends Horde warlocks from the clefts of Orgrimmar into the dry expanses of the Barrens in search of a missing grunt named Dogran. His mate, Zankaja, fears the worst after days of silence, sending the practitioner to question Dogran's superior at the Crossroads. Unraveling Dogran's fate forms a crucial step in the warlock ritual to bind a succubus. On the bluffs of Orgrimmar, Zankaja waits in quiet dread. Her mate Dogran was assigned to the Crossroads on an honorable promotion, yet his scheduled return has long passed without a single word. Unaware of the intricate dark arts pulling strings behind the scenes, she reaches out to a sympathetic traveler to seek answers from his commander, Gazrog.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1509-03e0814558a31b350b59/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["quest:1510"] = {
  hash = "2a641f",
  fullHash = "2a641f",
  text = "News of Dogran. This quest sends Horde adventurers deep into the foothills of the Stonetalon Mountains to contact the Darkspear troll Ken'zigla at Malaka'jin. An injured grunt from Camp Taurajo named Dogran lies wounded, and the first runner sent to fetch a lifesaving herbal draught never returned. Dogran, a Horde grunt stationed at Camp Taurajo in the southern Barrens, was grievously wounded during a skirmish against entrenched quilboar. The grunts with him made it back and tried to rescue him, but his wounds had festered so badly that they were afraid to move him without patching him up first. Desperate for a potent remedy, Taurajo sent word north to the Crossroads, hoping to procure a traditional healing draught prepared by the jungle trolls of Malaka'jin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1510-70c54c296f99da3f48ac/1-0000.mp3", duration = 43.8334694, start = 0},
  },
}
P.transport["quest:1511"] = {
  hash = "5ae481",
  fullHash = "5ae481",
  text = "Ken'zigla's Draught. Ken'zigla's Draught is an urgent courier task in the Horde warlock chain to summon a succubus. Entrusted with a potent medicinal concoction from Malaka'jin in the Stonetalon Mountains, the warlock must rush across Kalimdor to Camp Taurajo to save an operative named Dogran. In the crags of the Stonetalon Mountains, the troll apothecary Ken'zigla anticipated trouble. Knowing that an earlier emissary sent to secure medicine for the missing scout Dogran never made it back, Ken'zigla prepared a second dose of his potent restorative draught. The concoction is volatile and powerful: half a dose grants a mortally wounded soldier the vigor to move without causing his injuries to hemorrhage, while the rest must be withheld until the next day to complete recovery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1511-087b46bfd3ed40cb5bba/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["quest:1512"] = {
  hash = "08112a",
  fullHash = "08112a",
  text = "Love's Gift. Love's Gift is the penultimate quest in the Horde warlock chain to summon and bind a succubus. After being tracked down and revived in the Barrens, the dying Grunt Dogran relinquishes a treasured keepsake to provide the bait necessary for the dark ritual. To summon and subjugate a succubus, a warlock requires a talisman of intense, unblemished emotion. Succubi feed on mortal desire and pervert genuine affection into anguish. Dogran's pendant carries the weight of authentic devotion and tragic parting. Returned to Gan'rul Bloodeye in the shadowy clefts of Orgrimmar, the talisman is cleaned and polished so its radiant emotional resonance can lure the devourer of souls across the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1512-e7fdccd660d65586cfcd/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["quest:1513"] = {
  hash = "c1a096",
  fullHash = "c1a096",
  text = "The Binding. The Binding is the final trial in an aspiring Horde warlock's quest to enslave a succubus in Orgrimmar. By using the devotion bound up in Dogran's Pendant at Neeru Fireblade's summoning circle, the warlock wrenches a demon from the Twisting Nether and breaks its will through force of arms and spellcraft. Beneath the clefts of Orgrimmar, deep within the tent of Neeru Fireblade, lies a summoning circle prepared for such hazardous work. Under the tutelage of Gan'rul Bloodeye, the warlock activates the rune-scribed circle and battles the summoned seductress. A warlock cannot simply call a demon into service; they must overpower it in single combat, bending its malevolent spirit to their sovereign will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1513-108d06c5f312e51dc13e/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["quest:1515"] = {
  hash = "1ebd9f",
  fullHash = "1ebd9f",
  text = "Dogran's Captivity. Dogran's Captivity is a vital trial in an aspiring Horde warlock's training, sending practitioners into the heart of a quilboar camp to rescue a captured orc warrior. Entrusted with a revitalizing concoction, the warlock must locate the battered Grunt Dogran and supply him with the strength needed to escape his captors. Grunt Logmar at Camp Taurajo refuses to risk Horde military manpower on a costly raid against the entrenched quilboar, leaving the fate of his comrade Dogran entirely in the hands of an enterprising warlock. Armed solely with Ken'zigla's Draught, the rescuer must venture north among the brambles and hostile camps to locate where Dogran is held captive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1515-2e9c9a0456f031a9f241/1-0000.mp3", duration = 38.9746939, start = 0},
  },
}
P.transport["quest:1529"] = {
  hash = "36c761",
  fullHash = "36c761",
  text = "Call of Water. Call of Water is an initiation rite that directs rising Horde shaman from the heights of Thunder Bluff toward the eastern shores of the Barrens. To commune with the cleansing element of water, an initiate must seek out the recluse Islen Waterseer. This meeting marks the first step on a spiritual journey to earn the Water Totem. Having mastered the unyielding earth and the untamed flame, an aspiring shaman is eventually deemed ready to study the deeper mysteries of the elements. In Thunder Bluff, trainers like Xanis Flameweaver recognize when a student has shown enough discipline to approach the fluid, cleansing spirit of water. The journey requires leaving the windswept mesas of Mulgore behind and traveling east across the sun-scorched plains of the Barrens. The path leads to Islen Waterseer, a quiet mystic who lives away from the bustling settlements, residing in a humble fishing shack on the eastern coast south of Ratchet and the mouth of the Southfury River. Standing at the edge of the great ocean, Islen reads the readiness of travelers by how the elements linger about them. Seeing the steady earth, the brisk wind, and the warmth of fire already bound to the seeker's spirit, she prepares them for the trials required to understand water's purity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1529-81fae569d7958db94679/1-0000.mp3", duration = 68.7020408, start = 0},
  },
}
P.transport["quest:163"] = {
  hash = "91a6fd",
  fullHash = "91a6fd",
  text = "Raven Hill. Reports of shifting shadows and flickering window light in the abandoned settlement of Raven Hill have set the Night Watch on edge. Dispatched by Elaine Carevin in Darkshire, travelers are sent west across the haunted woods to confront whatever sinister presence has taken shelter among the ruins. To the rangers of the Night Watch, the far western edge of Duskwood has long been surrendered to the dead and the wilderness. Yet complete abandonment would be preferable to unexpected activity. Calor, a watcher patrolling the gloomy roads, noticed movement among the silent houses of Raven Hill two nights in a row, punctuated by the unsettling flicker of a lantern in a window. In a land plagued by ghouls, skeletons, and beasts, any unexplained signs of life demand immediate investigation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_163-0b24e255986698984e50/1-0000.mp3", duration = 45.4530612, start = 0},
  },
}
P.transport["quest:1653"] = {
  hash = "e7af2b",
  fullHash = "e7af2b",
  text = "The Test of Righteousness. The Test of Righteousness marks the transition from defending the innocent in Westfall to embarking on the construction of a paladin's sacred weapon. Entrusted by Duthorian Rall, the initiate travels to Ironforge to bring glad tidings to the devout smith Jordan Stilwell. Having stood guard over Daphne Stilwell during a harrowing Defias ambush on her Westfall homestead, a paladin initiate returns to Cathedral Square to report. Duthorian Rall recognizes that word must reach her husband, Jordan Stilwell, who left for Ironforge believing his family in jeopardy. Rall sends the young knight to deliver the relief in person, serving both as an act of fellowship and the prelude to a deeper undertaking. Jordan Stilwell was originally destined for the holy order of paladins, yet chose to honor his father's craft as a master weapon-smith without ever forsaking his faith. Setting up his anvil outside the gates of Ironforge to work in the bracing mountain air, Jordan relies on his spiritual devotion to guide his hammer. Upon hearing that his wife survived the Defias assault, his profound gratitude moves him to aid the paladin in forging a blessed weapon of righteousness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1653-c5d580f6de431354159c/1-0000.mp3", duration = 64.235102, start = 0},
  },
}
P.transport["quest:167"] = {
  hash = "613dc5",
  fullHash = "613dc5",
  text = "Oh Brother. . .. \"Oh Brother. . .\" is an Alliance mission given by Wilder Thistlenettle in Stormwind City. Distraught over a cave-in during an expedition into the depths beneath Moonbrook, Wilder asks adventurers to search the labyrinthine mines for his missing sibling, Foreman Thistlenettle, or recover his Explorers' League Badge. Wilder Thistlenettle and his brother entered the cavernous subterranean tunnels beneath Moonbrook as members of a mining company. However, things turned catastrophic when hostile thieves swarmed the area and a violent cave-in sealed off the lower tunnels. Wilder managed to escape to Stormwind, but his brother and the rest of the crew were left trapped behind the rubble.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_167-11528da95ab403189e09/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["quest:1698"] = {
  hash = "786b71",
  fullHash = "786b71",
  text = "Yorus Barleybrew. Yorus Barleybrew is an Alliance warrior summons directing seasoned fighters out of Stormwind toward the borderlands of Redridge. Issued by martial trainers across the Alliance capitals, it sends ambitious combatants to meet an eccentric dwarf laying down a deadly challenge at the Lakeshire Inn. Warrior trainers across the Alliance capitals, including Kelv Sternhammer, Wu Shen, and Darnath Bladesinger, keep a close eye on fighters who have outgrown basic drills. When an apprentice proves their mettle around their twentieth season, these masters pass along word of a dwarf named Yorus Barleybrew. Rather than issuing a standard military directive, Barleybrew has put out an open wager and a test of arms to any Alliance warrior bold enough to answer. Barleybrew has stationed himself at the tavern in Lakeshire, right on the front lines of Redridge's struggle against encroaching gnolls and Blackrock orcs. Those who track him down find a boastful dwarf with a hearty drink in hand, ready to size up any challenger who claims to possess real fighting spirit. For warriors seeking to prove themselves beyond the safe cobbled streets of the capital, his trial marks an initiation into harsher frontier battles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1698-e3324600fd222e42d04e/1-0000.mp3", duration = 66.795102, start = 0},
  },
}
P.transport["quest:1716"] = {
  hash = "b4865f",
  fullHash = "b4865f",
  text = "Devourer of Souls. Devourer of Souls is a pivotal rite of passage for Alliance warlocks dispatched from Stormwind to learn the summoning of a succubus. Directed by Gakin the Darkbinder, initiates must trek halfway across the world into the hazardous wildlands of the Barrens to seek counsel from Takar the Seer. Beneath the Slaughtered Lamb in Stormwind's Mage Quarter, Gakin the Darkbinder instructs promising warlocks on their next major summons: the succubus. Described as a devourer of souls, a destroyer of hearts, and a dominator of minds, this demonic entity cannot be summoned blindly into Azeroth. It requires a potent lure, specifically an object tied to pure love, to tease it forth from the Twisting Nether so that the practitioner may defeat and bind it. Procuring such a token demands wisdom that Stormwind's covens cannot provide locally. To track down the required catalyst, Gakin sends his pupils across the Great Sea to Kalimdor. Deep in the arid expanse of the Barrens, near the Horde settlement of Camp Taurajo, sits Takar the Seer. For an Alliance warlock, reaching Takar requires braving wilderness heavily patrolled by hostile centaur, quilboar, and Horde warriors, serving as an unstated test of survival before the summoner can even begin preparing the ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1716-b6b2c9c19dbb5353501f/1-0000.mp3", duration = 76.1730612, start = 0},
  },
}
P.transport["quest:1717"] = {
  hash = "1bdbdd",
  fullHash = "1bdbdd",
  text = "Gakin's Summons. A summons delivered to promising Alliance warlocks in Ironforge, directing them south to Stormwind. Gakin the Darkbinder awaits beneath the city's Mage Quarter to oversee their advancement into commanding greater fiends. Demonology remains a practice conducted entirely in shadows across Alliance lands. In Ironforge, Lago Blackwrench quietly keeps tabs on wandering practitioners on behalf of the brotherhood in Stormwind. When a warlock shows sufficient mastery over their initial minions, word travels quickly. Lago passes along the directive: drop whatever business keeps you in the snowy mountains of Khaz Modan and report south without delay. Deep beneath the cobblestones of Stormwind's Mage Quarter, beneath the tavern known as The Slaughtered Lamb, Gakin the Darkbinder coordinates the development of the city's warlocks. Gakin views every capable student as a valuable, hazardous investment. Receiving his summons marks the threshold of true demonic binding, beginning the trials required to subjugate a succubus from the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1717-6911c20fcf2988d9ec40/1-0000.mp3", duration = 58.4881633, start = 0},
  },
}
P.transport["quest:1738"] = {
  hash = "b95c6f",
  fullHash = "b95c6f",
  text = "Heartswood. Heartswood is an Alliance warlock quest that sends practitioners deep into Ashenvale to recover the branch of an ancient, tragic tree. Sent by the hermit Takar the Seer on behalf of Gakin the Darkbinder, warlocks seek this romantic relic as a potent bait to lure and subjugate a succubus in Stormwind. According to Takar the Seer, the Heartswood tree sprang from the spot where two night elf lovers, Anathera and Latherion, fell together during the War of the Ancients ten thousand years ago. Nourished by their final breaths and eternal devotion, the tree grew as a pure emblem of undying romance. To mortal senses it is a sacred tragic monument, but to practitioners of the dark arts, concentrated emotional energy makes potent magical fuel. Succubi feed upon mortal passions, desire, and emotional torment. Takar realizes that ordinary temptations pale in comparison to an artifact suffused with thousands of years of pure, undying devotion. A piece of the Heartswood provides Gakin the Darkbinder with the exact catalyst required to bait one of these cunning demons across the Nether into the summoning circle in Stormwind's Mage Quarter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1738-4771caae754fee280747/1-0000.mp3", duration = 65.8285714, start = 0},
  },
}
P.transport["quest:1739"] = {
  hash = "056ca2",
  fullHash = "056ca2",
  text = "The Binding. The Binding is the final initiation ritual for Alliance warlocks seeking to command a succubus in Stormwind. Using the enchanted core obtained from the Heartswood, the practitioner enters the summoning circle beneath The Slaughtered Lamb to drag forth and physically overpower the demon. Once defeated, the demon's will is chained, binding its servitude to the summoner. Hidden beneath the floorboards of The Slaughtered Lamb in Stormwind's Mage Quarter lies a cavernous crypt dedicated to forbidden arts. Far from the watchful eyes of the city watch and the Cathedral of Light, the city's covert warlock enclave conducts its most dangerous rituals here. Summoning circles etched into stone channel the raw forces of the Nether, allowing ambitious initiates to pierce the veil between worlds. Summoning a succubus requires far more than merely chanting incantations. A warlock must bring a focus—in this case, the prepared Heartswood Core—and cast a ritual of breach at the circle. Succubi are known to corrupt, seduce, and overwhelm even fortified minds. To establish absolute mastery, the summoner must cut the beast down in single combat, banishing its physical form back to the Twisting Nether while securing its true tether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1739-ef335ba1f49b2315e31b/1-0000.mp3", duration = 71.68, start = 0},
  },
}
P.transport["quest:1793"] = {
  hash = "fcb10b",
  fullHash = "fcb10b",
  text = "The Tome of Valor. The Tome of Valor is a foundational trial for Alliance paladins coming into their own. Directed by paladin mentors in Stormwind and Ironforge, initiates are challenged to prove that their courage and devotion to protecting the innocent match their martial prowess. To wield the Holy Light in battle requires more than heavy armor and martial discipline. As young paladins reach greater heights in their training, instructors in the Cathedral of Light and the Hall of Mysteries demand proof of their inner resolve. The lessons of the Tome of Valor test an initiate's readiness to confront terrifying evils—from dragons to demons—without faltering or abandoning those who cannot defend themselves. Bravery under mortal threat is considered as essential to a holy warrior as their weapon and shield. Through the trials laid out in the Tome of Valor, paladins learn that raw strength is hollow without an unwavering vow to shelter the helpless. Facing genuine peril ensures that when darkness falls upon the Alliance, its defenders will stand firm rather than break.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1793-f167959292bb5d3357f1/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["quest:1824"] = {
  hash = "90536c",
  fullHash = "90536c",
  text = "Trial at the Field of Giants. Trial at the Field of Giants is a warrior rites quest issued by Ruga Ragetotem at Camp Taurajo. As part of their training, martial aspirants are dispatched south into the swarming mounds of the Field of Giants to slay alien insectoid invaders. Candidates must harvest several still-twitching antennae and rush them back before the biological proof goes dormant. Warrior trainers among the Horde rarely accept mere martial competence without testing fortitude and urgency. Ruga Ragetotem challenges growing warriors at Camp Taurajo to prove themselves against an unfamiliar adversary. Aspirants are not just ordered to slay the encroaching creatures; they must sever fresh antennae and return to Taurajo within half an hour before the harvested tissue ceases twitching, demanding rapid navigation of the southern Barrens. The targets of the trial are the silithid hives burgeoning in the Field of Giants, nestled beneath massive fossilized ribcages. These crawling, chitinous insects are recent arrivals to the Barrens, disturbing the tauren hunters and shamans who watch the savannas. Ruga notes with dread that their presence bodes ill for Kalimdor, making the extermination test serve a dual purpose: proving a young warrior's combat instincts while gathering intelligence on a looming ecological menace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1824-63021dc9289667b8d1ec/1-0000.mp3", duration = 74.8669388, start = 0},
  },
}
P.transport["quest:1825"] = {
  hash = "b27b31",
  fullHash = "b27b31",
  text = "Speak with Thun'grim. This errand directs rising Horde warriors to Thun'grim Firegaze, an acclaimed orc blacksmith camping in the Barrens. Having proved themselves through demanding physical trials, warriors are invited to have custom armor forged in recognition of their valor. The quest serves as the crucial bridge connecting general warrior testing with the crafting of Brutal Armor. After proving their mettle against the silithid hives during the Trial at the Field of Giants, Horde warriors earn more than simple praise from Ruga Ragetotem. Word of their endurance and martial prowess quickly reaches Thun'grim Firegaze, a renowned orc smith who maintains a camp perched on a ridge east of the Crossroads. Recognizing a warrior worthy of his craft, Thun'grim sends word that he wishes to fashion them an exceptional suit of battle mail. Thun'grim Firegaze does not forge for ordinary soldiers. For an armorsmith of his reputation, steel must match the spirit of the one who carries it into battle. Reaching his camp signifies that a warrior has advanced past simple militia drills and is ready to undertake the grueling, specialized tasks required to gather rare crafting reagents across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1825-88eae1541f8de916ac54/1-0000.mp3", duration = 68.3885714, start = 0},
  },
}
P.transport["quest:1999"] = {
  hash = "5c3df7",
  fullHash = "5c3df7",
  text = "Tools of the Trade. Tools of the Trade is an initiation mission for Horde rogues given by Mennet Carkad in the Undercity. Ordered by Lord Varimathras, agents must obtain lockpicking gear and infiltrate Ambermill to recover sensitive Kirin Tor reports detailing Dalaran's current state. Following the interrogation of one of their prisoners, the Deathstalkers learned that vital intelligence concerning the ruins of Dalaran lies hidden in Ambermill. Silverpine Forest remains a precarious front line, and the human mages guarding the village guard their communications fiercely. Under the orders of Lord Varimathras, Deathstalker handler Mennet Carkad directs promising operatives to bypass Kirin Tor sentries and secure the Dalaran Status Report. Unlike straightforward assassinations, this mission serves as a practical proving ground in infiltration and lockpicking. Operatives are outfitted with specialized thieves' tools from Estelle Gendry before marching into hostile Kirin Tor territory. Cracking the secured chest in Ambermill demonstrates that an operative has progressed beyond raw street brutality into an indispensable espionage asset for the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1999-7c2d51873f074e6901ee/1-0000.mp3", duration = 65.3583673, start = 0},
  },
}
P.transport["quest:20"] = {
  hash = "8d6e4d",
  fullHash = "8d6e4d",
  text = "Blackrock Menace. Marshal Marris of Lakeshire tasks adventurers with culling the aggressive Blackrock orcs encroaching upon Redridge. By seizing their battleworn axes, the town's defenders hope to break the siege tightening around the settlement. Lakeshire finds itself hemmed in on multiple fronts, but none pose so dire a threat as the Blackrock orcs spilling over from the fiery Burning Steppes. Having pushed south into Redridge, these veteran raiders have seized strongholds and roam the craggy passes. Their presence keeps the townspeople effectively penned inside the settlement, cutting off trade, foraging, and travel along the northern roads. Marshal Marris, commander of the beleaguered Lakeshire guard, cannot spare a detachment to assault their positions outright. Instead, he enlists roaming adventurers to bleed the invaders' forward scouts and foot soldiers. By demanding their crude, battleworn axes as proof of death, Marris seeks to thin the invaders' numbers both around Stonewatch to the north and in the rugged pockets of southeastern Redridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_20-b804034d0839870e02c7/1-0000.mp3", duration = 59.0889796, start = 0},
  },
}
P.transport["quest:2040"] = {
  hash = "7de974",
  fullHash = "7de974",
  text = "Underground Assault. Underground Assault is an Alliance quest offered by Shoni the Shilent in Stormwind City's Dwarven District. Tasked with aiding the displaced gnomes, adventurers venture into the Deadmines to salvage an intact power core from a goblin shredder. This stolen component is destined to power drilling machines intended to spearhead the liberation of Gnomeregan. Following the catastrophic fall of Gnomeregan to the primitive troggs, surviving gnomish tinkerers have been forced into exile across Khaz Modan and Stormwind. Rather than wallowing in defeat, engineers like Shoni the Shilent are already devising mechanical operations to breach their lost home. The primary obstacle is the dense, subterranean rock surrounding the technocratic city, requiring massive tunneling engines known as gyrodrillmatic excavationators. Lacking the necessary localized power grids in human lands, the gnomes have turned their sights to an unlikely and volatile alternative: goblin heavy machinery operating in the criminal underworld. Deep within the twisting shafts of the Deadmines in Westfall, Edwin VanCleef's Defias Brotherhood employs goblin engineers to manufacture war machines, including a fully operational goblin shredder. Shoni directs Alliance operatives to infiltrate this foundry, destroy or dismantle the lumbering automaton, and recover its specialized heart—the Gnoam Sprecklesprocket. By commandeering the potent goblin power supply, the exiled gnomes gain the raw mechanical output needed to bore through the subterranean perimeter and launch a counteroffensive to reclaim Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2040-40f09331b884abbbf484/1-0000.mp3", duration = 89.7306122, start = 0},
  },
}
P.transport["quest:2078"] = {
  hash = "1bc6ec",
  fullHash = "1bc6ec",
  text = "Gyromast's Revenge. Gelkak Gyromast seeks payback against the local murlocs who plundered his wrecked ship along the Darkshore coastline. To carry out his vendetta, the eccentric captain sends adventurers to reactivate his mechanical first mate, the Threshwackonator 4100. Stranded upon the misty strands of Darkshore, Gelkak Gyromast refuses to accept defeat at the hands of the shore-dwelling murlocs. Having salvaged the pieces needed to fuel his schemes, the eccentric captain sets his sights on complete retaliation against the tribe and their chief. Rather than wading into the surf with cutlass in hand, Gelkak relies on heavy engineering to exact his vengeance, entrusting a winding key to any landlubber brave enough to handle his mechanical subordinate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2078-2f2164758c819c780597/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["quest:2098"] = {
  hash = "0657a1",
  fullHash = "0657a1",
  text = "Gyromast's Retrieval. Shipwrecked on the misty coast of Darkshore, the eccentric gnome pirate Gelkak Gyromast seeks aid to restore his mechanical first mate. His vital winding key was shattered upon the rocks and scavenged by the local wildlife and murlocs. Recovering the three pieces is the first step toward getting his crew back in working order. Gelkak Gyromast is an odd sight along the gloomy sands of Darkshore: a gnome pirate stranded far from the typical sea routes of the South Seas. According to Gelkak, his vessel met an unfortunate end just off the coastline after being attacked and sunk by aggressive threshadons. Washing ashore amid the flotsam, he found himself utterly marooned and separated from his trusty crew. Gelkak's most pressing concern is not provisions or gold, but his first mate. Activating and operating this companion requires a specialized key, which shattered into three distinct fragments when Gelkak crashed onto the rocky shoals. Before he could gather the fragments, the indigenous wildlife—scuttling reef crawlers on the beach, towering foreststriders near the woods, and scavengers from the local Greymist murloc tribe—snatched the shiny metal pieces away.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2098-40d282a9428deb3d8637/1-0000.mp3", duration = 66.5077551, start = 0},
  },
}
P.transport["quest:2282"] = {
  hash = "cb87d9",
  fullHash = "cb87d9",
  text = "Alther's Mill. Alther's Mill is a pivotal training assignment given to Alliance rogues by Lucius in Lakeshire. Dispatched to the nearby mill with a set of thieves' tools, initiates are tasked with infiltrating an area under Blackrock orc scrutiny to crack a locked chest and retrieve a token of thievery. In Lakeshire, rogue instructors do not bother with abstract lectures when a locked chest can teach the lesson faster. Lucius sends promising operatives northeast along the road to Alther's Mill, equipping them with their first set of thieves' tools. To earn their formal Certificate of Thievery, novices must slip into the abandoned mill, pick open Lucius's personal lockbox, and bring back the token cached within. While Alther's Mill was once an ordinary lumber outpost, it has recently drawn the dangerous attention of the Blackrock orcs encroaching upon Redridge. Lucius gleefully treats the encroaching warmongers as an added layer of practical examination. Prowling through enemy-held territory to pick locks undetected is precisely the kind of trial SI:7 expects its agents to survive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2282-241a72b8c63f61fa7e50/1-0000.mp3", duration = 59.9771429, start = 0},
  },
}
P.transport["quest:235"] = {
  hash = "c39a16",
  fullHash = "c39a16",
  text = "The Ashenvale Hunt. Issued by Warcaller Gorlach in Orgrimmar, this directive summons budding Horde adventurers northward beyond the Barrens into the ancient forests of Ashenvale. Players are directed to report to Senani Thunderheart at Splintertree Post to participate in the ongoing hunt and reinforce the Horde's expanding frontier. Orgrimmar buzzes with martial fervor, but the young city requires vast amounts of timber, meat, and secure trade routes to sustain its growth. Warcaller Gorlach serves as the voice of the Horde's high command, directing seasoned wanderers and new blood alike toward active campaigns. For warriors coming of age in Durotar and the Barrens, the ancient woodlands of Ashenvale represent the next testing ground for both glory and survival. Crossing the northern border of the Barrens brings travelers directly into Ashenvale, where the Horde maintains two primary bastions: Splintertree Post nestled in the eastern woods and Zoram'gar Outpost along the western coast. Senani Thunderheart coordinates operations at Splintertree Post, organizing trackers and hunters to tame the beast-choked canopy and push back against hostile night elven sentinels disputing the Horde's claims.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_235-0e49123be0106e36099b/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["quest:240"] = {
  hash = "c25c5c",
  fullHash = "c25c5c",
  text = "Return to Jitters. Return to Jitters concludes Chef Grual's culinary errand in Duskwood. Having prepared his infamous 'crab' cakes using the gooey legs of the local venom web spiders, Grual sends you back to the starving, terrified hermit at Raven Hill. Delivering the meal finally satisfies Jitters' desperate hunger. Duskwood is short on conventional livestock and sea life, leaving Chef Grual at the Scarlet Raven Tavern to improvise with whatever the blighted forest provides. His renowned 'Dusky Crab Cakes' contain no actual crab meat at all, relying instead on gooey legs harvested from the venom web spiders creeping through the wood. Grual considers this resourceful cooking; anyone with a delicate stomach might view it with horror. Jitters spends his days huddled at Raven Hill, utterly consumed by fright and paralyzed by whatever horrors drove him out of the woods. Weak with terror and unable to muster the courage to hunt or forage for himself, his empty stomach only amplifies his distress. Receiving the warm cakes brings a rare moment of relief to the trembling vagrant, who is far too hungry to question what kind of 'crab' Chef Grual used.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_240-ac371e2a509b81b0a8e5/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["quest:2458"] = {
  hash = "acbad9",
  fullHash = "acbad9",
  text = "Deep Cover. Deep Cover is an undercover assignment given to promising Horde rogues by Shenthul in Orgrimmar. The mission dispatches the operative to the Venture Company drilling grounds at Sludge Fen to establish secret contact with an embedded agent of the Shattered Hand. The Shattered Hand operates as the clandestine intelligence and assassin guild of the Horde, quietly guarding Orgrimmar's interests through ruthlessly practical means. For an entire year, the guild labored to slip an operative into the hierarchy of the rapacious Venture Company. That asset, Taskmaster Fizzule, managed to ingratiate himself into their industrial drilling outpost north of Sludge Fen. Operating deep within mercenary lines leaves no margin for error. Because Fizzule maintains a ruthless persona to satisfy his corporate overseers, any unannounced visitor risks immediate attack. To verify their identity, arriving rogues must fire twin flares from a designated signaling gun within sight of his tower, approach quietly, and perform the secret salute of the Shattered Hand before receiving his report on the Venture Company's escalating schemes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2458-2ee3c84ba18de53c0e96/1-0000.mp3", duration = 62.9028571, start = 0},
  },
}
P.transport["quest:2460"] = {
  hash = "6e5db8",
  fullHash = "6e5db8",
  text = "The Shattered Salute. The Shattered Salute is an initiation ritual overseen by Shenthul within the Cleft of Shadow in Orgrimmar. By learning this distinct sign of recognition, budding rogues are taught how to safely identify fellow operatives of the Shattered Hand in the field. Within the dark tunnels of the Cleft of Shadow, the Shattered Hand operates as the clandestine intelligence and assassination arm of Thrall's Horde. Given the dangerous and secretive nature of their assignments, operatives cannot rely on overt banners or standard military heraldry. Shenthul instructs newly inducted rogues in the Shattered Salute, a specific gesture meant to serve as an unmistakable, silent signal among allies. Mastering the salute is not merely a ceremonial exercise; it is vital tradecraft. Rogue agents sent into perilous territory or tasked with infiltrating rival factions must verify contacts without alerting bystanders or targets. Shenthul insists that an operative be able to recognize and mirror the gesture effortlessly before entrusting them with covert fieldwork.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2460-56385fb79d9d62f67a6c/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["quest:2478"] = {
  hash = "4751de",
  fullHash = "4751de",
  text = "Mission: Possible But Not Probable. This critical assignment tests a Horde rogue's stealth, thievery, and combat skills against a rogue Venture Company outpost in the northern Barrens. Operatives infiltrate an oil tower, assassinate Grand Foreman Puzik Gallywix, and seize a potent chemical concoction for the Shattered Hand. North of the Sludge Fen oil rigs, the Venture Company maintains an isolated drilling tower. Under orders from Taskmaster Fizzule, an embedded Shattered Hand operative posing as a Venture Company supervisor, rogues are instructed to use classic underworld methods rather than outright assault. Fizzule asks rogues to pickpocket a key directly off Foreman Silixiz and keep it for him before mounting an ascent through heavily altered workers and sentries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2478-13478adafaa9d2f12ff0/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["quest:2479"] = {
  hash = "19f34a",
  fullHash = "19f34a",
  text = "Hinott's Assistance. Hinott's Assistance is an urgent journey undertaken by Horde rogues suffering from a debilitating tropical toxin. Contracted during an infiltration mission in the Barrens, the affliction requires the specialized expertise of Serge Hinott in Tarren Mill. Seeking his aid promises both a life-saving cure and instruction in the art of concocting deadly poisons. Following the daring infiltration of the Venture Company's tower north of the Sludge Fen, rogues find themselves afflicted by Zanzil's altered mixture. The poison wreaks havoc on the body, dulling reflexes and threatening life itself. Recognizing the severity of the affliction, rogue trainer Shenthul in Orgrimmar admits that local remedies are inadequate and directs the poisoned operative across the sea to the Eastern Kingdoms. The search for a cure leads south through the continent of Lordaeron to the village of Tarren Mill in Hillsbrad Foothills. There resides Serge Hinott, an apothecary whose fascination with virulent brews makes him ideally suited to analyze the exotic sample. While ordinary healers recoiled from Zanzil's venom, Hinott treats the deadly compound with professional glee, eager to dissect the foul concoction and instruct worthy rogues in brewing their own venoms.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2479-714f3cc50704b70196da/1-0000.mp3", duration = 72.6204082, start = 0},
  },
}
P.transport["quest:276"] = {
  hash = "5566de",
  fullHash = "5566de",
  text = "Tramping Paws. Tramping Paws is an Alliance task given by Rethiel the Greenwarden at the Greenwarden's Grove in the Wetlands. Troubled by the surging Mosshide gnoll population near the Gate of Algaz, the bog beast protector tasks adventurers with culling their numbers before their fires and trampling paws ruin the bog. For many years, the Mosshide gnolls inhabited the Wetlands without utterly overwhelming its natural order. Lately, however, their pack numbers have exploded south toward the pass of Dun Algaz. Their heavy boots and pawprints trample rare fen flora, and their crude logging strips vital groves to feed their campsite blazes. Left unchecked, the burgeoning packs threaten to degrade the fragile marsh ecology. Rethiel the Greenwarden watches over the marsh with an eye for balance rather than civilization. To the Greenwarden, the issue is not that gnolls exist, but that their runaway population outstrips what the Wetlands can support. By driving Mosshide gnolls and mongrels back into manageable numbers, adventurers help preserve the wetlands and earn the reluctant approval of an ancient wilderness guardian.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_276-ff10e762043e7e839f9f/1-0000.mp3", duration = 65.4106122, start = 0},
  },
}
P.transport["quest:4021"] = {
  hash = "074dac",
  fullHash = "074dac",
  text = "Counterattack!. Following the systematic elimination of their local chieftains in the Barrens, the Kolkar centaur mount a desperate retaliation out of Desolace. An invading force marches directly upon Regthar Deathgate's outpost west of the Crossroads, culminating in a fierce confrontation with Warlord Krom'zar. The campaign against the Kolkar centaur in the Barrens struck deep into their tribal leadership. With Barak Kodobane, Verog the Dervish, and Hezrul Bloodmark dead, the remaining centaur found themselves shattered and without direction. In response to this humiliation, word traveled west across the mountains to their ancestral homeland in Desolace. Rather than scattering into the scrubland, a fresh contingent of hardened Kolkar warriors rallied and crossed into the Barrens, burning for blood and retribution against the fledgling Horde encampments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4021-fda13c6f8114c0d478ac/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:442"] = {
  hash = "87dadb",
  fullHash = "87dadb",
  text = "Assault on Fenris Isle. Assault on Fenris Isle is the climactic military directive issued by High Executor Hadrec to eradicate the Scourge stronghold in Silverpine Forest. To break the Lich King's grip upon Lake Lordamere, Forsaken agents are sent to storm Fenris Keep and take the head of the necromancer Thule Ravenclaw. For weeks, Fenris Isle has stood as a poisonous blister in the heart of Lake Lordamere. While the Forsaken secured the western roads and established their presence at the Sepulcher, the Scourge entrenched themselves inside Fenris Keep. Commanded by the powerful necromancer Thule Ravenclaw, this island outpost threatened not only Silverpine Forest but the southern waterways leading toward the Undercity itself. High Executor Hadrec recognizes that the Forsaken will never truly hold Silverpine while a servant of the Lich King conducts vile experiments right off their eastern shores.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_442-eccd410a470316f802cc/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["quest:455"] = {
  hash = "0bc8a4",
  fullHash = "0bc8a4",
  text = "The Algaz Gauntlet. The Algaz Gauntlet is an urgent military mission to fight through Dun Algaz, a critical mountain pass linking Loch Modan to the Wetlands. Orcs of the Dragonmaw clan have entrenched themselves in the tunnels, threatening to sever Ironforge's vital lifeline to Menethil Harbor. Adventurers are tasked with cutting down the orcish vanguard and delivering word of the invasion to Valstag Ironjaw. Dun Algaz serves as the solitary overland mountain pass carving through the crags between Loch Modan and the marshy basin of the Wetlands. For the dwarves of Ironforge, this stone corridor is essential for trade, troop movements, and supplies heading to Menethil Harbor, the Alliance's primary coastal port in the region. Should the pass fall, Ironforge's connection to the western seas is effectively strangled, leaving isolated outposts cut off from dwarven reinforcements. While remnants of the Dragonmaw clan have long haunted the hills and ruins of the Wetlands following the Second War, their sudden, organized push into Dun Algaz marks an aggressive escalation. Instead of lingering in their marshland enclaves, Dragonmaw scouts and grunts have seized the tunnels and fortified the pass. Mountaineer Rockgar enlists brave Alliance travelers to shatter this blockade by slaying the encroaching orcs and carrying word of the assault directly to Valstag Ironjaw in Menethil Harbor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_455-3332da62a12dbda9f213/1-0000.mp3", duration = 81.2408163, start = 0},
  },
}
P.transport["quest:463"] = {
  hash = "ce0d3a",
  fullHash = "ce0d3a",
  text = "The Greenwarden. \"The Greenwarden\" is an Alliance breadcrumb quest directing travelers deeper into the marshes of the Wetlands. Sent by First Mate Fitzsimmons from Menethil Harbor, adventurers venture northeast into the swamp to seek out a mysterious entity rumored to dwell among the beasts. Around the docks of Menethil Harbor, sailors and wanderers trade breathless stories of a beast lurking out in the swamp. First Mate Fitzsimmons paints the Greenwarden as an appetite with legs, warning gullible seekers that stepping off the dry road means being bitten in two by 'ol' Greenie.' To the dockside folk, anything massive lurking out in the murky waters is just another man-eating hazard of the marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_463-f24878e52d0b4aa2f7ff/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["quest:468"] = {
  hash = "e7a33e",
  fullHash = "e7a33e",
  text = "Report to Mountaineer Rockgar. Report to Mountaineer Rockgar is an Alliance breadcrumb quest directing adventurers north from the guard posts of Loch Modan toward Dun Algaz. Mountaineer Kadrell dispatches capable travelers to join Rockgar, who is organizing a vital expedition into the sodden lowlands of the Wetlands. It serves as the gateway passage connecting the dwarven homeland to northern territories. Dun Algaz represents the crucial artery between Loch Modan and the marshy expanses of the Wetlands. Built into the northern mountain ridge, the fortified pass has long guaranteed safe passage for trade, messengers, and military detachments moving between Ironforge and Alliance settlements further north. With tensions rising along the borders, Mountaineer Kadrell keeps a close watch on travellers passing through, recruiting hardy volunteers to reinforce the northern outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_468-88f7cbd34e948702eadf/1-0000.mp3", duration = 48.6661224, start = 0},
  },
}
P.transport["quest:469"] = {
  hash = "6db502",
  fullHash = "6db502",
  text = "Daily Delivery. Daily Delivery is an errand on behalf of the dwarven hunter Einar Stonegrip, who asks travelers heading toward Menethil Harbor to deliver cured crocolisk hides to the local tanner. Rather than facing domestic friction at home, Einar relies on passing adventurers to keep his supply line moving. Out in the marshlands, Einar Stonegrip makes his living hunting the local wildlife, particularly the aggressive crocolisks that lurk along the waterways. While he gathers plenty of valuable skins, delivering them requires a trip home to Menethil Harbor. Reluctant to confront his wife Sida during a rough patch in their marriage, Einar prefers to stay in the field and hand his parcels off to passing travelers instead. The destination for these hides is James Halloran, a tanner operating within Menethil Harbor. Halloran relies on regular deliveries from local hunters to craft boots and cure leather for merchants and sailors passing through the port. Having noticed Einar's week-long absence, the tanner easily deduces the marital spat behind the proxy delivery, musing that his own wife might need to intervene and smooth things over with Sida.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_469-519dde9b1dfeeefd3fd3/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["quest:493"] = {
  hash = "5bcfb3",
  fullHash = "5bcfb3",
  text = "Journey to Hillsbrad Foothills. Journey to Hillsbrad Foothills is a Horde courier task connecting the Forsaken research efforts in Silverpine Forest with their outpost in Tarren Mill. Entrusted with sensitive notes from Apothecary Renferrel, the traveler journeys south into the disputed Hillsbrad Foothills to deliver vital biological research to Apothecary Lydon. This dispatch reflects the intense pressure Lady Sylvanas Windrunner places upon the Royal Apothecary Society to produce a weapon of mass devastation. Since breaking free from the Lich King's iron grip, Lady Sylvanas Windrunner has harbored a single-minded ambition: the development of a New Plague engineered to eradicate both living enemies and the Scourge. To achieve this, the Royal Apothecary Society operates under relentless pressure from the Banshee Queen. Because distance isolates their laboratories, researchers scattered across Lordaeron must continuously share raw chemical data and test findings to accelerate their sinister breakthrough. Apothecary Renferrel, operating out of the Sepulcher in Silverpine Forest, directs couriers to deliver his recent findings to his colleague, Apothecary Lydon. The trek winds south through the shadowed pine woods and down into the open, rolling pastures of Hillsbrad Foothills. There, nestled beneath the Alterac Mountains, lies Tarren Mill—a vital Forsaken hub and laboratory staging ground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_493-6a96cd78f7654d30d0ca/1-0000.mp3", duration = 76.2514286, start = 0},
  },
}
P.transport["quest:494"] = {
  hash = "a40691",
  fullHash = "a40691",
  text = "Time to Strike. \"Time to Strike\" is a Horde reconnaissance mission that transitions scouts across the Hillsbrad Foothills border to the military hub of Tarren Mill. Delivering Deathstalker Lesh's coded signal to High Executor Darthalia marks the transition from quiet surveillance to coordinated offensive operations against the local human populace. Perched along the high ground near the border between Silverpine Forest and the Hillsbrad Foothills, Deathstalker Lesh monitors the movements of human settlers and militia in the valley below. The Deathstalkers operate as the eyes and ears of the Undercity, surveying enemy settlements before any military deployment. Rather than risk abandoning her watchpost, Lesh entrusts passing Horde travelers to relay her gathered intelligence down the road to Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_494-f5a9b812dd5230e05345/1-0000.mp3", duration = 43.9379592, start = 0},
  },
}
P.transport["quest:5"] = {
  hash = "6f5d9f",
  fullHash = "6f5d9f",
  text = "Jitters' Growling Gut. Stranded and terrified in the ruins of Raven Hill, the paranoid vagrant Jitters is desperate for real sustenance after subsisting on weeds and insects. He begs passing adventurers to travel east to Darkshire and convince Chef Grual to prepare a hot batch of his famous Dusky Crab Cakes. Raven Hill has become a den of ravenous undead and lurking beasts, leaving the eccentric hermit Jitters trapped in hiding for weeks. Prowling through dilapidated shanties under perpetual gloom, he has survived solely on dirt-dwelling grubs and wild weeds. Starved of civilized comfort, his nerves and stomach are pushed to their absolute limits. Desperate for any reminder of safety, Jitters dreams of the seasoned patties crafted at the Scarlet Raven Tavern in Darkshire. He sends travelers across the haunted road to seek out Chef Grual, hoping Grual will agree to whip up a batch of Dusky Crab Cakes to quiet his violently growling gut.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5-260dee9d67a58ffdffb6/1-0000.mp3", duration = 53.8383673, start = 0},
  },
}
P.transport["quest:5042"] = {
  hash = "8dd697",
  fullHash = "8dd697",
  text = "Agamaggan's Strength. Agamaggan's Strength is a repeatable ritual offered by the captive quilboar Mangletooth in Camp Taurajo. By exchanging red Blood Shards harvested across the Barrens, travelers are granted the potent physical might revered by the Razormane tribe's greatest warriors. It fuels Mangletooth's bitter hatred of the rival Bristleback quilboar. The quilboar revere the ancient boar demigod Agamaggan, whose spilled blood is said to have formed the thorny red Blood Shards scattered across the Barrens. To the quilboar, drawing upon these crystals is a sacred rite, imbuing their front-line fighters with terrifying physical might. While held captive in Camp Taurajo, the elder Razormane shaman Mangletooth is eager to impart this strength to Horde champions, claiming your foes will cower just as they do before the Razormane's most formidable champions. Mangletooth's generosity is entirely driven by spite. Captured and caged by the orcs and tauren, the old quilboar harbors a searing grudge against the rival Bristleback tribe, the enemies of his own Razormane. Since he cannot break his chains to slaughter them personally, he uses the ancient gifts of Agamaggan as currency, rewarding anyone who decimates the Bristleback tribes and strips their lands of their sacred Blood Shards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5042-7a59ad55f618bac2e30f/1-0000.mp3", duration = 70.5567347, start = 0},
  },
}
P.transport["quest:5043"] = {
  hash = "f9f331",
  fullHash = "f9f331",
  text = "Agamaggan's Agility. Agamaggan's Agility is a repeatable blood shard ritual offered by the captive quilboar Mangletooth in Camp Taurajo. By offering crystalline blood shards mined from the earth of the Barrens, travelers are blessed with the unerring swiftness and accuracy of the quilboar's ancient boar god. Throughout the Barrens, strange crimson minerals known as blood shards jut from the soil, especially near quilboar encampments and colossal brambles. Quilboar tradition teaches that these crystals were formed from the spilled blood of Agamaggan, the Great Boar Ancient who perished fighting the Burning Legion in the War of the Ancients. Even locked inside a wooden cage at Camp Taurajo, the elder quilboar Mangletooth retains the knowledge to channel this dormant divine power for anyone willing to supply the stones. Quilboar hunters and scouts pride themselves on ruthless accuracy and blinding quickness in the scrublands. In exchange for four blood shards, Mangletooth invokes the latent energy of the fallen demi-god, infusing the petitioner with the predatory instincts and supple grace of his people's best stalkers. Though he grunts with disdain at outsiders, Mangletooth honors his pact, weaving Agamaggan's power into a temporary mantle of agility.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5043-0363928d67657e79b190/1-0000.mp3", duration = 69.9036735, start = 0},
  },
}
P.transport["quest:5044"] = {
  hash = "964416",
  fullHash = "964416",
  text = "Wisdom of Agamaggan. Wisdom of Agamaggan is a repeatable Horde quest offered by the captive quilboar Mangletooth in Camp Taurajo. By presenting blood shards gathered across the Barrens, spellcasters can partake in the ritualistic magic of the ancient boar god Agamaggan. Held prisoner by the Horde at Camp Taurajo, the quilboar Mangletooth trades the magical secrets of his race for crimson crystals known as blood shards. According to quilboar belief, these shards crystallized from the spilled blood of Agamaggan, the towering boar Demigod who perished in the War of the Ancients. Mangletooth claims the geomancers and shaman of his tribes rely on these shards to channel divine power into their rituals. While other offerings coax physical resilience or swiftness from the shards, the ritual of Wisdom focuses strictly on intellect and arcane capability. For the exchange of four blood shards, Mangletooth invokes the boar god's spirit on behalf of the player, wishing them cunning in their confrontations before parting with an ominous reminder of mortality.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5044-ebd77f9b39a127648d5a/1-0000.mp3", duration = 60.0816327, start = 0},
  },
}
P.transport["quest:5045"] = {
  hash = "a08b53",
  fullHash = "a08b53",
  text = "Rising Spirit. Rising Spirit is a ritual blessing offered by the captured Razormane geomancer Mangletooth at Camp Taurajo. In exchange for blood shards wrested from his Bristleback rivals, Mangletooth channels the ancient power of Agamaggan to invigorate a champion's willpower and spiritual fortitude. Held in a cage at Camp Taurajo, the Razormane elder Mangletooth possesses deep knowledge of quilboar geomancy and ancestral magic. While other tribes may boast of raw combat ferocity, Mangletooth takes immense pride in his people's spiritual devotion to their creator, the Great Boar Agamaggan. He teaches that an unbroken spirit is what sustains a warrior when strength alone falters in battle, driving champions onward when defeat seems certain. To invoke this spiritual elevation, Mangletooth demands blood shards—crystallized fragments steeped in the ancient blood of Agamaggan that seeped into the red earth ten thousand years ago. By bringing him shards harvested from across the Barrens, particularly from his Bristleback enemies, you provide the raw spiritual conduit needed for him to weave a blessing of rising spirit that bolsters your will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5045-ea4c5ade5602bcb87ee4/1-0000.mp3", duration = 63.8432653, start = 0},
  },
}
P.transport["quest:5046"] = {
  hash = "5510d4",
  fullHash = "5510d4",
  text = "Razorhide. Razorhide is a repeatable ritual offered by the captive quilboar Mangletooth in Camp Taurajo. By offering him blood shards infused with the life essence of the Ancient boar god Agamaggan, warriors and wanderers can gain a powerful blessing of hardened skin and resilience before heading into combat. The quilboar trace their ancestry and power directly to Agamaggan, the Great Boar who perished battling the Burning Legion thousands of years ago. His blood soaked into the soils of the Barrens, calcifying into crystalline blood shards that still thrum with ancient power. Even though the quilboar remain sworn enemies of the Horde, Mangletooth—held in a cage at Camp Taurajo—is willing to trade their sacred knowledge in exchange for these precious fragments. Natural quilboar physiology grants them thick hides and protective quills, but tribal warriors invoke Agamaggan's blessing of Razorhide to further shield themselves from enemy blades and claws. By channeling four blood shards, Mangletooth mimics this tribal rite for outsiders, magically bolstering an adventurer's defenses so their bones remain unbroken and their skin resists trauma in the wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5046-d11ea07f7f2a88079320/1-0000.mp3", duration = 64.4963265, start = 0},
  },
}
P.transport["quest:5052"] = {
  hash = "c40b99",
  fullHash = "c40b99",
  text = "Blood Shards of Agamaggan. Mangletooth, a captive Razormane quilboar held at Camp Taurajo, reveals the sacred origin of the blood shards scattered throughout the Barrens. Imbued with the fallen demigod Agamaggan's life essence, these red minerals grant potent ancestral magic to anyone skilled enough to channel them. In exchange for the shards, the spiteful prisoner offers to share the primal boons of his god with the Horde. According to quilboar lore, the blood of the Ancient Boar God, Agamaggan, did not merely cause giant thorn mazes to erupt across the arid plains when he fell ten thousand years ago during the War of the Ancients. His divine blood seeped deep beneath the soil, infusing the subterranean minerals and crystallizing into blood-red stones. The quilboar revere these shards as sacred remnants of their creator, harvesting them from both mineral seams and holy grounds to serve as totems of battle and sorcery. Caged at Camp Taurajo by the tauren, Mangletooth harbors a bitter grudge against his own kind, claiming his tribe betrayed and cast him out. Deprived of his freedom and his connection to the magic of his people, he eagerly strikes a bargain with adventurers. By exchanging blood shards, Mangletooth bypasses his captivity to channel Agamaggan's power directly into Horde champions, gleefully unleashing them as an instrument of vengeance against the very quilboar who turned their backs on him. In his captivity, Mangletooth speaks reverently of the quilboar's holiest sanctuary to the south: Razorfen. To the quilboar tribes, the sprawling briars of Razorfen Kraul and Razorfen Downs are literally formed from the fallen demigod's colossal skeleton and tusks. He warns that Razorfen Downs rests within Agamaggan's gaping maw itself—a holy threshold said to devour and crush any intruders who enter without the Boar God's favor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5052-05b68262c42eeada4c91/1-0000.mp3", duration = 104.594286, start = 0},
  },
}
P.transport["quest:516"] = {
  hash = "06430e",
  fullHash = "06430e",
  text = "Beren's Peril. Beren's Peril is a Horde quest directed by Shadow Priest Allister from the Sepulcher. Agents of the Forsaken have caught wind of a hidden conclave of Scourge massing inside a secluded cave tucked into the southern Silverpine hills, aiming to strike them down before an offensive can begin. Word reached Shadow Priest Allister at the Sepulcher that mindless servants of the Lich King were massing deep within southern Silverpine Forest. Left unchecked, these Scourge forces posed an immediate threat to Forsaken operations throughout the region. Rather than waiting for the assault to land, Allister directs scouts to take the initiative and eliminate the gathering horde inside their secluded lair before they can mobilize. Beren's Peril itself is an obscure cavern network carved into the hills south of the Dalaran-aligned settlement of Ambermill. The treacherous terrain makes the cavern easy to overlook, approached only by navigating around the southern slopes. Within its shadows dwell the Ravenclaw drudgers and guardians, entrenched remnants of the plague whose destruction helps ensure the Forsaken maintain their tenuous hold over the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_516-5f8263e844522bb20b8c/1-0000.mp3", duration = 62.955102, start = 0},
  },
}
P.transport["quest:530"] = {
  hash = "c098a9",
  fullHash = "c098a9",
  text = "A Husband's Revenge. A Husband's Revenge is the conclusion to a tragic tale of past betrayal carried into undeath. Raleigh Andrean, a Forsaken residing in the Undercity, charges travelers with tracking down his former friend Valdred Moray, who murdered his wife in life. When Raleigh Andrean received the engraved ring carried from Silverpine Forest, it rekindled memories of his mortal life that undeath had mostly withered away. Among those memories was a profound betrayal: his close friend, Valdred Moray, had murdered Raleigh's wife, Deliah. While the chill of the Scourge and subsequent Forsaken existence dulled Raleigh's capacity for grief and love, his thirst for retribution remained entirely intact.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_530-e168717fb3c6d37b6b97/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:5321"] = {
  hash = "1a905a",
  fullHash = "1a905a",
  text = "The Sleeper Has Awakened. Kerlonian Evershade, a recently awakened Druid of the Claw, struggles to remain awake on his journey toward Maestra's Post in Ashenvale. Entrusted with his Horn of Awakening, travelers must shepherd the lethargic druid along the forested border, rousing him when he drifts into slumber and defending him against wild furbolgs and sinister cultists. For millennia, the Druids of the Claw slept within barrows, communing with the wild spirits across the Emerald Dream. Though the Third War demanded their awakening, shaking off centuries of hibernation does not come easily to every mind. Kerlonian Evershade set out south from Darkshore toward Ashenvale to rendezvous with Liladris Moonriver, but exhaustion overtook him shortly into his trek. Finding himself helplessly prone to sudden naps along the wilds, he relies on a brass Horn of Awakening and passing allies to keep his feet moving. The path connecting Darkshore to Ashenvale is far from tranquil. As Kerlonian meanders southward, his vulnerable state invites aggression from the surrounding wilderness. In Twilight Vale, corrupted Blackwood furbolgs stalk the roadway, while farther south into Ashenvale, members of the shadowy Dark Strand cult lurk in ambush. Escorting the groggy druid requires a vigilant watch, as Kerlonian will simply lie down to sleep wherever he stands unless forcefully roused with the horn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5321-7d8ee806962f9229d4ac/1-0000.mp3", duration = 79.6734694, start = 0},
  },
}
P.transport["quest:5643"] = {
  hash = "1c38e1",
  fullHash = "1c38e1",
  text = "Shadowguard. Shadowguard is a priestly calling issued to Darkspear troll priests who find themselves far from home in the Forsaken capital of Undercity. Aelthalyste recognizes that the young troll has matured enough for their tribe's sacred rites and sends them back to Orgrimmar. In the Valley of Spirits, the priest trainer Ur'kyo awaits to guide them into a vital tier of spiritual protection. Even in the gloom of the Undercity, the bonds of faith and tribal tradition remain strong. Forsaken priest trainer Aelthalyste observes visiting troll priests closely, noting when an initiate has grown potent enough to face their culture's trials. Rather than imposing the bleak philosophy of the Forsaken priesthood upon them, she directs the troll back across the Great Sea to the ancestral ways of their own elders. Upon arriving in Durotar, the priest makes their way to the mystic enclave of the Valley of Spirits in Orgrimmar. There, Ur'kyo tends to the spiritual needs and ancient rituals of the Darkspear tribe. He welcomes the returning initiate, preparing them for an essential rite of passage that bridges the priest's bond to the loa with practical spells vital for warding off harm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5643-c12378ca406819a9a7a6/1-0000.mp3", duration = 65.9853061, start = 0},
  },
}
P.transport["quest:5644"] = {
  hash = "385412",
  fullHash = "385412",
  text = "Devouring Plague. Devouring Plague is a rite of passage quest for Forsaken priests journeying far from Lordaeron. Guided by the Forsaken priest trainer Miles Welsh in Thunder Bluff, the adept is directed back across the seas to Aelthalyste in the Undercity to unlock a signature manifestation of Shadow magic. While visiting Thunder Bluff, Forsaken priests who have honed their mastery over divine and shadowy disciplines are evaluated by Miles Welsh, a Forsaken priest posted among the tauren. Recognizing that an acolyte has grown sufficiently in power, Miles bids them return to the Ruins of Lordaeron rather than attempt to impart these higher mysteries himself in Kalimdor. Awaiting beneath the city ruins within the Undercity's War Quarter is Aelthalyste, one of the foremost mentors of Forsaken priesthood. She watches over the development of shadow-weaving acolytes, ensuring that the potent, draining blight known as the Devouring Plague is entrusted only to those capable of wielding its corruptive force without succumbing to it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5644-603ef614c9c16e2a3d72/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["quest:5645"] = {
  hash = "53f890",
  fullHash = "53f890",
  text = "A Lack of Fear. A Lack of Fear is a rite-of-passage summons for dwarven priests, calling promising disciples back to the grand halls of Ironforge. High Priest Rohan awaits in the Mystic Ward to test their discipline and bestow teachings tailored to their growing resilience. Priests serving the Alliance abroad are routinely directed by their local mentors to report back to their order's senior clergy. For dwarven disciples, that guidance leads straight to High Priest Rohan in the heart of Ironforge's Mystic Ward. The summons marks a turning point where basic spiritual practice gives way to deeper, trial-tested applications of holy magic. High Priest Rohan does not simply teach liturgy; dwarven tradition views the Light as a shield and an unyielding bulwark in physical conflict. Reporting for this test acknowledges that the initiate has survived baptism through fire in the wider world and possesses the mettle required to master fear itself on the front lines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5645-e78e30ccb9b486eb76cf/1-0000.mp3", duration = 54.5436735, start = 0},
  },
}
P.transport["quest:5646"] = {
  hash = "210604",
  fullHash = "210604",
  text = "Devouring Plague. Devouring Plague is a rite-of-passage quest for Forsaken priests who have ventured to Kalimdor to learn from the Darkspear tribe. The troll priest trainer Ur'kyo in Orgrimmar directs promising Forsaken initiates to return home to Undercity, where Aelthalyste waits to impart deeper teachings of shadow. While the orcs and tauren have little inclination toward priestly worship, the Darkspear trolls and the Forsaken share a curious theological bond within the Horde. In Orgrimmar, the troll priest trainer Ur'kyo guides those drawn to spiritual power. Yet he recognizes that Forsaken initiates must ultimately master the sinister arts unique to their own condition. In a mutual show of respect between their peoples, Ur'kyo directs wandering Forsaken back to Lordaeron to complete their training. Beneath the ruins of Lordaeron, Priestess Aelthalyste tends to the flock in the Undercity's War Quarter. Forsaken priests walk a solitary, grueling path shaped by their turn toward shadow, tempering the painful touch of the Holy Light with the devastating affliction of Shadow magic. When an initiate attains sufficient prowess, Aelthalyste gathers them close to bestow the affliction known to their kind as the Devouring Plague.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5646-93f2d53c9fcd950b6391/1-0000.mp3", duration = 69.7469388, start = 0},
  },
}
P.transport["quest:5672"] = {
  hash = "2e57a6",
  fullHash = "2e57a6",
  text = "Elune's Grace. Elune's Grace is a rite of recognition offered to devout night elf priests in Darnassus. Upon proving their faith and discipline through their early journeys, priests are called before Priestess Alathea to receive deeper instruction in the divine mysteries of the Moon Goddess. Within the Temple of the Moon in Darnassus, the Sisterhood of Elune guides young acolytes from their first prayers to mastery of lunar magic. Night elves do not look upon the Holy Light in the same manner as humans or dwarves; their faith is inextricably tied to the Mother Moon, Elune. When a novice priest reaches a significant milestone in their devotion, senior mentors take notice, marking the disciple as ready to shoulder greater divine power. Priestess Alathea extends this summons on behalf of the Sisterhood. She acknowledges that the acolyte's dedication has elevated them beyond the common flock, granting them access to traditions preserved across millennia. Accepting the rite seals the priest's bond to Elune, unlocking specific protective wards and lunar invocations unique to the kaldorei faith.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5672-ae4d5ac2eaf86b8a4ab4/1-0000.mp3", duration = 61.2832653, start = 0},
  },
}
P.transport["quest:5674"] = {
  hash = "a2ddc3",
  fullHash = "a2ddc3",
  text = "Elune's Grace. Elune's Grace is a rite of advancement for developing night elf priests, marking their readiness to wield divine talents unique to their people. Guided from local outposts like Dolanaar back to the sacred Temple of the Moon in Darnassus, candidates present themselves before Priestess Alathea to prove their devotion. Within the Sisterhood of Elune, a priest's journey involves more than simply mastering standard prayers of mending and smiting. As acolytes grow in experience, they reach a threshold where they are deemed ready to receive blessings granted exclusively to the kaldorei. Local mentors such as Laurna Morninglight in Dolanaar lack the authority to bestow these deeper arts, directing promising disciples back to the cultural and spiritual heart of their order. The quest directs initiates across Teldrassil to the grand Temple of the Moon in Darnassus. There, beneath the gaze of the high priesthood, Priestess Alathea evaluates whether the petitioner is truly prepared to bear the goddess's defensive mantle. Learning Elune's Grace symbolizes reaching true maturity within the priesthood, bridging the gap between raw potential and formal service to the goddess.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5674-bbda5c9d9d38c89d1a11/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["quest:5676"] = {
  hash = "da2ca7",
  fullHash = "da2ca7",
  text = "Arcane Feedback. Arcane Feedback is a rite of passage for Alliance priests in Stormwind City, granted by High Priestess Laurena in the Cathedral of Light. Reaching a deeper communion with faith, the priest is instructed in wards designed to counter hostile practitioners of the arcane. It represents the Church's practical defense against raw sorcery and rogue spellcasters. Within the sunlit cloisters of the Cathedral of Light, High Priestess Laurena reminds acolytes of an enduring peril: arcane magic. While the Holy Light brings healing, warmth, and divine order, raw magical energies are volatile and often court corruption or catastrophe. To endure against warlocks, renegade sorcerers, and magical beasts, devout priests are taught that faith alone must sometimes be shaped into an active ward against ambient spells. Arcane Feedback trains the mind and spirit to punish hostile spellcasters for channeling power against the faithful. Rather than simply deflecting magical volleys, this discipline mirrors arcane energy back into its source, burning through the caster's own mana reserves while causing agony. Laurena imparts this spell to human priests stepping out into the wider world, ensuring the Cathedral's emissaries never travel defenseless against sorcery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5676-b0e4254fe14f7357b8f2/1-0000.mp3", duration = 71.4187755, start = 0},
  },
}
P.transport["quest:5677"] = {
  hash = "789bec",
  fullHash = "789bec",
  text = "Arcane Feedback. Arcane Feedback is a priest quest given by High Priest Rohan in Ironforge to human acolytes visiting Khaz Modan. Rohan directs the developing priest home to the Cathedral of Light in Stormwind to receive teachings tailored specifically to the traditions of humankind. It marks a key moment of progression where young disciples begin mastering racial manifestations of their faith. When a human priest seeks advanced spiritual tutelage in the halls of the Mystic Ward, High Priest Rohan greets them with reverence but sets a boundary. While dwarven and human priests share devotion to the Holy Light, each civilization nurtures its own particular rites, disciplines, and defensive prayers. Rather than imparting Ironforge's unique secrets, Rohan sends human clergy back to their cultural roots in Elwynn, ensuring they master their people's distinct heritage. Upon returning to Stormwind City, the acolyte reports to High Priestess Laurena within the grand Cathedral of Light. Laurena is relieved to see Rohan's guidance reach the traveler, welcoming them back just as their nascent powers begin to flourish. This return paves the way for deeper initiation into the Kingdom of Stormwind's spiritual practices, preparing practitioners to wield the Holy Light against the rising threats encircling the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5677-4739e0961b5b309bb011/1-0000.mp3", duration = 72.8293878, start = 0},
  },
}
P.transport["quest:5678"] = {
  hash = "faf1da",
  fullHash = "faf1da",
  text = "Arcane Feedback. \"Arcane Feedback\" is an Alliance priest quest that directs human priests training in Darnassus back home to Stormwind. Sent by Priestess Alathea at the Temple of the Moon, the journey highlights the deep cultural rift regarding magic between the night elves and the Eastern Kingdoms. Upon returning to the Cathedral of Light, High Priestess Laurena prepares the acolyte for deeper theological instruction. Priestess Alathea oversees visiting priests within the tranquil halls of the Temple of the Moon in Darnassus. While she recognizes the formal alliance between the kaldorei and the humans of Stormwind, she harbors deep misgivings about human magical and spiritual practices. Night elf society views arcane power as inherently volatile and dangerous, shaped by ten millennia of grief following the War of the Ancients. Even divine rites from humanity that blur the lines between radiant faith and arcane mechanics make night elf clergy distinctly uneasy. Despite her hesitation, Alathea honors the bond between the Alliance races and releases the visiting acolyte to answer a recall from the Cathedral of Light. High Priestess Laurena has sent couriers across the seas to gather growing human priests for advanced training. Stepping back into Stormwind, the acolyte leaves behind the moonlit groves of Elune to embrace the grand stone sanctuaries and golden radiance of the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5678-a9af2a5983ba33c91976/1-0000.mp3", duration = 79.3338776, start = 0},
  },
}
P.transport["quest:5679"] = {
  hash = "299a45",
  fullHash = "299a45",
  text = "Devouring Plague. Devouring Plague is a rite of instruction offered to Forsaken priests who have proven their dedication to shadow magic. Granted by Priestess Aelthalyste in the Undercity, the teaching marks an acolyte's initiation into one of the most dreaded curses woven by the undead priesthood. In the murky cloisters of the War Quarter, Priestess Aelthalyste guides Forsaken practitioners through the grim arts of the Shadow. While living priests of other races appeal to the Holy Light or ancestral spirits for their power, the Forsaken have forged their own spiritual doctrines. Devouring Plague represents the crystallization of their philosophy: inflicting suffering upon their foes while leeching the stolen vitality back into their own decaying bodies. Aelthalyste does not offer the knowledge of the plague lightly. The spell is considered a weapon of potent malice, intended to turn the tide against the Scourge and the Scarlet Crusade. When imparting the spell, Aelthalyste warns her disciples to hone their command over it through relentless practice, cautioning that far greater trials lie ahead for those who seek to master the dark arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5679-258361ffa11731e77a17/1-0000.mp3", duration = 62.3281633, start = 0},
  },
}
P.transport["quest:6284"] = {
  hash = "ada45b",
  fullHash = "ada45b",
  text = "Arachnophobia. Arachnophobia is a Horde bounty quest targeting Besseleth, an ancient and colossal predator haunting southern Stonetalon Mountains. Posted on a roadside notice near Windshear Crag, the bounty directs adventurers into Sishir Canyon to claim the spider matriarch's fang for Maggran Earthbinder at Sun Rock Retreat. Putting an end to her reign makes the mountain roads safer for night travelers. Travelers along the main thoroughfare south of Windshear Crag will spot a weathered wanted poster warning of the dangers to the west. Sishir Canyon and Webwinder Path have been completely overrun by eight-legged predators. At the heart of this webbed menace sits Besseleth, an unusually large, orange-hued spider who commands her brood and ambushes anyone daring to stray off the path after sunset. The bounty on Besseleth is offered by Maggran Earthbinder, a tauren resident of Sun Rock Retreat. Maggran has a personal score to settle with the matriarch: during a previous encounter, he was nearly killed when struck by Besseleth's massive two-foot fang. Though he managed to fight her off and limp to safety, the lingering wound serves as a constant reminder of the danger lurking in the canyon shadows. By having an adventurer claim Besseleth's Fang, Maggran hopes to secure the passes so trade and travel to Sun Rock Retreat can flourish without fear.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6284-7ec16fc07b32b807fe6b/1-0000.mp3", duration = 77.844898, start = 0},
  },
}
P.transport["quest:6481"] = {
  hash = "704a15",
  fullHash = "704a15",
  text = "Earthen Arise. Deep within Boulderslide Ravine, the shaman Mor'rogal discovers a slumbering Earthen named Goggeroc sealed inside a Resonite cask. Fearing the raw destructive power an ancient being of stone could unleash upon Kalimdor, he sends a champion to shatter the cask and strike Goggeroc down before the creature can recover its full strength. While investigating the vermin infestation in Boulderslide Ravine, scouts discovered a strange relic nestled among the kobolds: a Resonite cask radiating unearthly force. Mor'rogal, a tauren shaman stationed in the Stonetalon Mountains, recognized the container for what it truly was—a prison and sanctuary housing Goggeroc, a dormant Earthen. These primordial creations of stone possess strength that outmatches mortal warriors, making the prospect of Goggeroc roaming free an existential threat to the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6481-6bfb7c0491de40e00356/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["quest:6547"] = {
  hash = "3d3fb3",
  fullHash = "3d3fb3",
  text = "Warsong Scout Update. Warsong Scout Update is a Horde communication task connecting the outpost commanders along the borders of Ashenvale with forward scouts watching the contested forest. Carrying strategic orders from Kadrak, couriers ensure the Warsong Clan maintains tight surveillance against ambushing night elves. It highlights the tenuous, hostile grip the Horde strives to maintain over their newly claimed territory. The borderlands of Ashenvale remain a powder keg where neither side yields an inch. Horde forces under Kadrak rely heavily on dispersed Warsong scouts stationed in high-risk outposts to track night elf movements and secure contested supply lines. Because the forest itself provides natural cover to the stealthy sentinels of the Alliance, regular reports and written updates are critical to keeping isolated scouts from being cut off and overwhelmed. For the Warsong clan, every stretch of forest cleared or occupied has been paid for in blood. The scouts watch constantly for retaliatory night elf raids aiming to reclaim the woodlands. Delivering Kadrak's orders reassures the vanguard that reinforcements and coordination remain active, allowing the scouts to report back that their defensive measures are succeeding despite continuous elven resistance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6547-147cd90887d19e1100b0/1-0000.mp3", duration = 71.2620408, start = 0},
  },
}
P.transport["quest:731"] = {
  hash = "f75f82",
  fullHash = "f75f82",
  text = "The Absent Minded Prospector. Deep in the southern ruins of Darkshore, Prospector Remtravel refuses to abandon his dig site without a prize to show the Explorers' League. Despite his severe forgetfulness and an infestation of hostile troggs, he insists on uncovering a mysterious fossil before retreating. Ensuring the dwarven researcher survives his erratic search allows word of his safety to reach his assistant back in Auberdine. Remtravel's Dig lies far to the south of Darkshore, nestled among ancient ruins that were supposed to hold forgotten secrets. Instead, the dwarven excavators struck into pockets of savage troggs, driving out the workers and leaving the camp under siege. While most would flee for Auberdine immediately, Prospector Remtravel became fixated on salvaging his findings. Refusing to leave empty-handed, he wanders right into the teeth of danger to recover an elusive fossil to justify the expedition's costs to the Explorers' League.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_731-5dcbb81e23f072a8cef4/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["quest:741"] = {
  hash = "d0077a",
  fullHash = "d0077a",
  text = "The Absent Minded Prospector. This errand delivers a strange petrified specimen recovered from the wild beaches of Darkshore to the Explorers' League outpost in Darnassus. Archaeologist Hollee refuses to abandon her distracted colleague in the field, entrusting the specimen's transport to a passing adventurer instead. The fossil's arrival in the night elven capital immediately captures the keen interest of Chief Archaeologist Greywhisker. Prospector Remtravel's excavations along the misty coast of Darkshore have unearthed a curious fossil, but digging deeper matters more to him than protocol. Archaeologist Hollee, unwilling to leave the wandering prospector alone amidst the shore's dangerous beasts and hostile cultists, remains behind to watch over him. In order to get the discovery documented, she requires an Alliance traveler to ferry the specimen up to Darnassus, where the dwarven guild maintains a scholarly delegation. Dwarves from Ironforge have crossed the Great Sea in force under the banner of the Explorers' League, eager to unearth ancient relics and lost history beneath the soil of Kalimdor. Receiving the artifact in the elven capital, Chief Archaeologist Greywhisker wastes no time in marveling over Remtravel's knack for uncovering ancient treasures. While night elves view their forests as living sanctuaries, the League views the ancient lands as an expansive archaeological dig waiting to be deciphered.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_741-080e699e68d130e1a42c/1-0000.mp3", duration = 79.7518367, start = 0},
  },
}
P.transport["quest:742"] = {
  hash = "637a7b",
  fullHash = "637a7b",
  text = "The Ashenvale Hunt. The Ashenvale Hunt is a summons dispatched to young Horde champions visiting Thunder Bluff, urging them north into the dense canopy of Ashenvale. Delivered by the city's heralds, the call directs travelers to report to Senani Thunderheart at Splintertree Post to take part in a proving hunt. Within the serene heights of Thunder Bluff, runners keep the burgeoning Horde informed of opportunities beyond the borders of Mulgore. Bluff Runner Windstrider carries an open invitation aimed at proven adventurers looking for greater challenges. With the Horde establishing footholds deep in the ancient forest north of the Barrens, young warriors are called upon to bolster those outposts and test their survival skills in a far harsher environment. Ashenvale represents both rich resources and severe peril for the Horde. Two prominent encampments anchor the faction's presence in the territory: Splintertree Post along the main road, and a remote outpost perched upon the western coast at Zoram Strand. Arriving at Splintertree Post puts incoming recruits directly under the wing of Senani Thunderheart, a veteran outdoorswoman organizing a massive hunt designed to tame the wilderness and claim glory for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_742-aa6e346e2fe2193e1094/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["quest:876"] = {
  hash = "5521a3",
  fullHash = "5521a3",
  text = "Serena Bloodfeather. This bounty task charges Horde adventurers with slaying Serena Bloodfeather, the matriarch driving harpy raids against Crossroads supply lines. Her campaign is a personal blood feud stemming from the Champion of the Horde Rexxar slaying her sister. Putting an end to Serena aims to shatter the coordination behind the harpy flock in the northern Barrens. The Witchwing harpies infesting the crags northwest of the Crossroads do not strike solely out of animalistic hunger. Their leader, Serena Bloodfeather, wages an explicit blood feud against the Horde. Years ago during the founding of Durotar, the wandering beastmaster Rexxar struck down Serena's sister, a notorious matriarch named Bloodfeather. Consumed by hatred for the nascent Horde, Serena has rallied her flock into an organized scourge intent on butchering supply trains, scouts, and merchants traveling the arid trails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_876-e4c3edda920467cb88f8/1-0000.mp3", duration = 48.64, start = 0},
  },
}
P.transport["quest:878"] = {
  hash = "28572a",
  fullHash = "28572a",
  text = "Tribes at War. Tribes at War is a Horde quest offered by the captive quilboar Mangletooth in Camp Taurajo. Trapped behind bars by the tauren, Mangletooth barters critical intelligence about quilboar incursions in exchange for the slaughter of rival Bristleback spiritual leaders. Caged in Camp Taurajo, the Razormane quilboar Mangletooth proves that captivity does not blunt old hatreds. The Barrens has long been contested between two dominant quilboar factions: the Razormane and the Bristleback. While the Horde struggles to secure its settlements and supply lines against sudden ambushes, Mangletooth offers valuable insight into who is truly tormenting Thork's outpost—provided a champion of the Horde first cuts down the Bristleback's most revered casters. Mangletooth directs adventurers north against the Bristleback's mystical core: their Water Seekers, Thornweavers, and Geomancers. Both tribes revere the earth and draw raw power from ancient magic tied to their demigod progenitor, Agamaggan. By eliminating their casters, the Horde strikes a crippling blow to Bristleback ritual strength, leaving them vulnerable to Razormane rivals and reducing pressure on nearby trails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_878-41d5f4d6b4318d5907e6/1-0000.mp3", duration = 69.0416327, start = 0},
  },
}
P.transport["quest:889"] = {
  hash = "e5d20d",
  fullHash = "e5d20d",
  text = "Spirit of the Wind. Spirit of the Wind is a repeatable ritual offered by the captive quilboar Mangletooth in Camp Taurajo. By channeling the residual power within Agamaggan's blood shards, Mangletooth infuses travelers with swiftness to outpace the vast savannas of the Barrens. In the arid sprawl of the Barrens, crossing open territory quickly can mean the difference between survival and falling to predatory beasts or wandering centaur warbands. The captive quilboar Mangletooth, imprisoned within Camp Taurajo, understands the latent power sleeping within the red crystalline blood shards scattered across the region. When handed ten of these relics, he draws upon their primeval resonance to bestow the Spirit of the Wind, granting travelers a burst of fleet-footed momentum to outrun the howling drafts of the plains. Quilboar tradition reveres Agamaggan, the Great Boar who shed his blood across central Kalimdor during the ancient War of the Ancients. Even in captivity, Mangletooth retains intimate knowledge of the wild god's rites. Channelling the god's spilled blood does not merely alter the flesh; it stirs wild vigor, allowing a runner to match the velocity of the galloping zhevra herds. Though the quilboar are bitter enemies of the Horde, Mangletooth remains willing to impart Agamaggan's boons to anyone willing to fuel his rituals with fresh shards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_889-74f024e7343c2bf10284/1-0000.mp3", duration = 76.277551, start = 0},
  },
}
P.transport["quest:89"] = {
  hash = "9f0b03",
  fullHash = "9f0b03",
  text = "The Everstill Bridge. The Everstill Bridge is a rebuilding effort led by Foreman Oslow in Lakeshire to repair the town's damaged stone bridge. Progress has ground to a halt because iron meant for the project was redirected into weapons during the last orc invasion, and the replacement caravan from Stormwind was ambushed by Redridge gnolls. The stone bridge spanning Lake Everstill is the lifeblood of Lakeshire, connecting the western roads back toward Elwynn Forest with the far bank and the northern passes. During the recent orc incursions, the town was pushed to the brink. With survival hanging in the balance, Lakeshire melted down its structural iron supplies to forge munitions, blades, and plate armor to repel the Blackrock invaders, leaving the bridge incomplete and vulnerable. Foreman Oslow petitioned the House of Nobles and Stormwind for fresh construction materials to finish repairs. A supply caravan laden with iron was dispatched, but it never arrived. A warband of Redridge gnolls ambushed the convoy along the road, carting away vital iron pikes and rivets into their camps in the northern hills. Without adventurous travelers willing to reclaim the stolen hardware, the bridge project remains stalled while gnolls and orcs tighten their grip on the mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_89-02eabe2ac6c36937bd69/1-0000.mp3", duration = 69.12, start = 0},
  },
}
P.transport["quest:891"] = {
  hash = "1ea3be",
  fullHash = "1ea3be",
  text = "The Guns of Northwatch. Captain Thalo'thas Brightsun in Ratchet has had enough of his merchant vessels being blasted to splinters by the Alliance gunners at Northwatch Hold. He hires Horde champions to march down the Merchant Coast, silence the hold's artillery officers, and take the badges of their fallen infantry. Northwatch Hold looms over the southern coast of the Barrens, established as a fortified bastion for the humans of Theramore. While intended to guard Alliance interests and monitor Horde activity in Kalimdor, the soldiers within have succumbed to severe paranoia. Viewing any unfamiliar sail as hostile, their rampart batteries open fire indiscriminately, threatening peaceful merchant traffic and the privateering vessels of Ratchet. Captain Brightsun refuses to let his ships be sunk without consequence. The strike against Northwatch targets its command: Captain Fairmount and her chief cannoneers, Whessan and Smythe. Striking them down and stripping Theramore medals from the garrison's soldiers leaves the hold's artillery disarrayed, granting Ratchet's maritime operations breathing room along the Merchant Coast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_891-5c3922fceb1d38b87f17/1-0000.mp3", duration = 61.675102, start = 0},
  },
}
P.transport["quest:898"] = {
  hash = "f7bb68",
  fullHash = "f7bb68",
  text = "Free From the Hold. Free From the Hold is an escort quest in the Barrens where Horde adventurers rescue Gilthares Firebough from human captors at Northwatch Hold. Captured after his transport was intercepted and sunk, the elf deckhand seeks a daring break out to reunite with his captain in Ratchet. Northwatch Hold stands as Theramore's military spearhead on the Barrens coast, vigilant and aggressive toward any perceived threat. That paranoia caught Gilthares Firebough in its net. His ship, running moonshine along the commercial lane between Ratchet and Booty Bay, was bombarded and sent to the ocean floor by Alliance forces. As the lone survivor plucked from the wreckage, Gilthares was thrown into Northwatch's dungeons accused of being an enemy agent conspiring against the Alliance. Despite his jailers painting him as a dangerous saboteur, Gilthares insists he is nothing more than a humble deckhand caught carrying illicit liquor. With the aid of Horde forces willing to strike at Northwatch, he makes a desperate bid for freedom, fighting his way out of the fortress and fleeing north up the shoreline to Ratchet. There, Captain Thalo'thas Brightsun welcomes the returned crewmate back into the fold of the Thalo'dan Privateers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_898-1fbd805131ec826ae080/1-0000.mp3", duration = 68.6236735, start = 0},
  },
}
P.transport["quest:899"] = {
  hash = "8cb0b8",
  fullHash = "8cb0b8",
  text = "Consumed by Hatred. Consumed by Hatred is a grim task given by Mankrik at the Crossroads in the Barrens. Tormented by the violent ambush that separated him from his wife, the grieving orc directs his agonizing uncertainty into a relentless vendetta against the Bristleback quilboar. He calls upon Horde travelers to slaughter the creatures in droves and return with a massive tally of their tusks. Standing under the harsh sun of the Crossroads, Mankrik is a warrior possessed by grief. After surviving a vicious raid by the quilboar that left him battered and his wife missing, he spends his waking hours watching the arid horizon for any sign of the pig men. His thirst for their blood remains unquenched despite the many he has personally cut down, driving him to seek help from fellow members of the Horde. Rather than seeking peace or solace, Mankrik demands trophies of raw slaughter: sixty Bristleback quilboar tusks. To him, each shattered tusk represents a measure of suffering returned upon the monsters that tore his life apart. While piles of bone cannot heal his grief or quell his desire for retribution, seeing the Bristlebacks bleed brings a fleeting, bitter satisfaction to the wounded warrior.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_899-1b04287da6b1b96373c2/1-0000.mp3", duration = 68.7020408, start = 0},
  },
}
P.transport["quest:913"] = {
  hash = "f9dcce",
  fullHash = "f9dcce",
  text = "Cry of the Thunderhawk. Cry of the Thunderhawk is the culmination of Jorn Skyseer's hunting trials in the southern Barrens. Entrusted by the elders at Camp Taurajo, a hunter must seek out a winged serpent soaring through the scrublands and bring back its wings to prove their mastery over the savanna's fiercest beasts. After proving their mettle against prowling plainstriders, prowlers, and agitated thunder lizards, hunters in the Barrens are directed toward their ultimate challenge by Jorn Skyseer. The thunderhawk is considered one of the most fierce aerial predators inhabiting the scrublands surrounding Camp Taurajo. Slaying one requires patience, sharp aim, and an awareness of the sky that few landbound predators possess. Returning with the thunderhawk's wings marks the end of a novice's tutelage under Camp Taurajo's watchful eyes. For the tauren, hunting is not mere slaughter but an ongoing spiritual walk in harmony with the Earthmother and the natural hierarchy of the wild. Besting such a proud creature shows that the hunter acts with strength, courage, and honor—virtues required before stepping out into harsher wildernesses beyond the central plains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_913-efc03a4a02bd1390d8ee/1-0000.mp3", duration = 64.7053061, start = 0},
  },
}
P.transport["quest:92706"] = {
  hash = "f1d0fb",
  fullHash = "f1d0fb",
  text = "WANTED: Bruuz. WANTED: Bruuz is a bounty posted by Gazlowe in the goblin port of Ratchet. A massive predatory shark has taken up residence near the harbor docks, threatening maritime traffic and coastal trade until someone puts an end to it. Ratchet thrives on merchant shipping, serving as the primary neutral gateway between Kalimdor and the Eastern Kingdoms. That steady stream of commerce makes the waters around the docks bustling and chaotic, but recently it has drawn a far more dangerous visitor. A gargantuan shark, dubbed 'Bruuz' by the frightened dockworkers, has begun prowling the bay. Rather than remaining in deep water, the beast aggressively targets small skiffs, local sailors, and offloading cargo, disrupting port operations. Gazlowe cannot afford to have vessels avoiding his port out of fear of getting mauled by sea life. So he has posted a public bounty notice calling on all anglers and promising a hefty reward. To claim it, a hunter must slay Bruuz and haul back the predator's dorsal fin as proof of the deed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92706-c5a04da2d1f8b99cf512/1-0000.mp3", duration = 60.4734694, start = 0},
  },
}
P.transport["quest:93"] = {
  hash = "772343",
  fullHash = "772343",
  text = "Dusky Crab Cakes. Chef Grual of Darkshire's Scarlet Raven Tavern has a secret behind his famous Dusky Crab Cakes: they contain no crab at all. Tasked with aiding the famished and nervous Jitters, adventurers are sent to harvest spider legs from the deadly arachnids roaming northern Duskwood to prepare the town's beloved snack. Duskwood has long suffered from isolation, dark magic, and severed supply routes, forcing the locals of Darkshire to adapt their cuisine. Chef Grual, the resident cook at the Scarlet Raven Tavern, solved his meat shortages by inventing the Dusky Crab Cake. Despite the name suggesting seafood from distant shores, Grual readily admits that the dish's distinctively tangy flavor comes entirely from the gooey legs of local giant spiders. To fulfill the order, Grual directs hunters north toward the foothills and riverbanks where Venom Web Spiders spin their snares. In a gloomy forest crawling with undead and feral beasts, harvesting fresh spider meat is hazardous work, yet it remains one of the few readily available protein sources in the blighted woods. Grual fries the seasoned arachnid limbs on a hot skillet until they skitter to a crisp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93-2008122406095d6b3829/1-0000.mp3", duration = 67.1869388, start = 0},
  },
}
P.transport["quest:94"] = {
  hash = "83dcdd",
  fullHash = "83dcdd",
  text = "A Watchful Eye. A Watchful Eye is an Alliance quest issued by the wizard Theocritus from the Tower of Azora in Elwynn Forest. Having established a basic scrying link against his rival Morganth, Theocritus directs adventurers east into Redridge Mountains to plant an enchanted focus upon an ancient lion statue watching the Tower of Ilgalar. From his tower in eastern Elwynn Forest, the mage Theocritus maintains a vigilant watch over dark spellcraft brewing in the nearby hills. His chief nemesis is Morganth, a vicious sorcerer of formidable power who has claimed the Tower of Ilgalar in the crags of Redridge Mountains. Seeking to uncover Morganth's sinister ambitions before they spill across the border, Theocritus developed the Eye of Azora to surveil the rogue wizard from a distance. While visual scrying affords some information, it is not enough to divine Morganth's deeper schemes. Theocritus entrusts travelers with the Glyph of Azora, commanding them to trek to the shadow of the Tower of Ilgalar. There, keeping a lonely watch for decades, stands an Old Lion Statue. Setting the glyph into a worn depression at the statue's base awakens an arcane conduit, linking the stone back to Azora and allowing Theocritus to delve straight into his rival's mind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94-7f14c5e68213bcc43cb3/1-0000.mp3", duration = 70.7918367, start = 0},
  },
}
P.transport["quest:942"] = {
  hash = "99a8e0",
  fullHash = "99a8e0",
  text = "The Absent Minded Prospector. This quest bridges an excavation mystery from Darkshore across the Great Sea to the Wetlands. Chief Archaeologist Greywhisker entrusts you with a strange Kalimdor fossil, directing you to Archaeologist Flagongut in Menethil Harbor to unlock its secrets. While examining the strange fossil uncovered in Darkshore, Chief Archaeologist Greywhisker notices a striking resemblance to a relic shown at an Explorers' League conference back in Ironforge. That earlier piece was presented by Archaeologist Flagongut, who was convinced that such fossils held latent powers waiting to be unlocked. Greywhisker believes Flagongut is the only dwarf capable of discerning what makes this Kalimdor find so extraordinary. Carrying the mysterious relic means undertaking a long journey out of Kalimdor to the Eastern Kingdoms. Flagongut was last seen waiting for an armed escort to the Whelgar Excavation Site while lodging at the Deepwater Tavern in Menethil Harbor. Delivering the fossil into his hands marks the turning point where a local Darkshore survey ties into a continent-spanning archaeological inquiry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_942-906fa06f0e8a82307ec5/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["quest:951"] = {
  hash = "781dd5",
  fullHash = "781dd5",
  text = "Mathystra Relics. This quest sends Alliance adventurers north along the coast of Darkshore to sift through the overgrown Ruins of Mathystra. Onu, an Ancient of Lore rooted in the Grove of the Ancients, seeks these ancient kaldorei artifacts to understand how the Twilight's Hammer cult is manipulating night elven sorcery for their sinister rites. To counteract this dark endeavor, Onu directs heroes to the Ruins of Mathystra, located along the northeastern shores of Darkshore. Long ago, Mathystra was a shining bastion of highborne civilization before it shattered during the Sundering. Though the city has collapsed into rubble, weeds, and naga infestation, powerful remnants of its original arcane and spiritual enchantments linger in shattered urns and ancient relics scattered across the stone foundations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_951-b3913ffb1b422d7812c7/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["quest:970"] = {
  hash = "7520ba",
  fullHash = "7520ba",
  text = "The Tower of Althalaxx. This quest marks a critical turn in the investigation of the sinister Cult of the Dark Strand, shifting the pursuit from the ruined Tower of Althalaxx in Darkshore across the border to Maestra's Post in Ashenvale. Delgren the Purifier dispatches adventurers into nearby cultist camps to secure a potent Glowing Soul Gem. Unlocking this artifact reveals the grim sorcery that fuels the cult's influence over the northern forests. After uncovering the ominous activities around the Tower of Althalaxx in northern Darkshore, reports led directly south into Ashenvale to Delgren the Purifier. Stationed at Maestra's Post, Delgren has long contended with the Cult of the Dark Strand encroaching on the ancient elven woods. Recognizing that the cult's threat spans across both territories, Delgren resolves to strike at the heart of their vile sorcery. Northeast of Maestra's Post lies the ruins of Ordil'Aran, now overrun by fanatical Dark Strand cultists. Delgren identifies that their operatives carry glowing soul gems—dark vessels enchanted with sinister magic that sustain the cult's power. By hunting down the cultists among the ruins and reclaiming one of these gems, Delgren intends to shatter their enchantment and expose the true source behind their malevolent rite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_970-cf1d138898fe746d4fc6/1-0000.mp3", duration = 71.3404082, start = 0},
  },
}
P.transport["quest:972"] = {
  hash = "7e0be3",
  fullHash = "7e0be3",
  text = "Water Sapta. Water Sapta is a transitional task bestowed upon young Horde shaman by Islen Waterseer along the coast of the Barrens. Imbued with a ritual brew, the shaman is sent across the Great Sea to the blighted lands of Silverpine Forest to face a corrupted spring. In the elemental traditions of the Horde's shaman, a sapta is an alchemical draught crafted to attune the senses directly to the spirits of the world. While common eyes perceive only tranquil streams or stagnant ponds, drinking a sapta pierces the veil of the physical plane, revealing the elemental beings dwelling within the current. Having demonstrated their dedication to the spirits, the shaman receives the concoction directly from Islen Waterseer, a hermit dwelling along the desolate shores south of Ratchet. Rather than testing the sapta in the arid valleys of Kalimdor, Islen commands the initiate to journey far across the Great Sea to the shadowy, forsaken woods of Silverpine Forest to confront an elemental corruption poisoning Lordaeron's streams.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_972-81fc6d3a4914b9471578/1-0000.mp3", duration = 61.4922449, start = 0},
  },
}
P.transport["quest:98362"] = {
  hash = "28f3e6",
  fullHash = "28f3e6",
  text = "To Thunder Bluff. To Thunder Bluff marks the triumphant return of a young tauren druid from their communion with the Cenarion Circle in Moonglade. Having earned the favor of the Great Cat Spirit, the initiate returns to Turak Runetotem on the Elder Rise to master the art of feline shapeshifting. After proving their insight and worth before Dendrite Starblaze and the Great Cat Spirit in the sacred groves of Moonglade, a young druid must carry the spirit's blessings back to Mulgore. The communion with such primal powers represents a pivotal milestone in a druid's training, bridging ancient night elven teachings with the tauren's own earthen heritage. Awaiting your return high atop the Elder Rise in Thunder Bluff is Turak Runetotem. While Dendrite facilitated communion with the spirit itself, it falls to Turak to guide the physical transformation. With the blessing of the Great Cat Spirit acknowledged, the elder trainer imparts the sacred knowledge required to adopt the swift, predatory shape of the cat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98362-6d12e48c5a77c0c7ddfe/1-0000.mp3", duration = 55.6669388, start = 0},
  },
}
P.transport["quest:98397"] = {
  hash = "bda39f",
  fullHash = "bda39f",
  text = "To Darnassus. To Darnassus is the culmination of a night elf druid's journey to commune with the Great Cat Spirit. After proving yourself to Dendrite Starblaze in Moonglade, you are sent back to the Cenarion Enclave to master the art of shifting into cat form. Having commune with the Great Cat Spirit through the guidance of Dendrite Starblaze in Moonglade, an aspiring night elf druid must return to Teldrassil. Starblaze acknowledges that you have proven yourself a worthy student and directs you back to your primary instructor, Mathrengyl Bearwalker, waiting beneath the boughs of the Cenarion Enclave in Darnassus. Upon arriving in Darnassus, Mathrengyl Bearwalker acknowledges that you have absorbed the wisdom of the Great Cat Spirit. In his eyes, every generation of druids faces a trial shaped by this ancient entity, which is as playful as it is deadly. With your connection established and your spirit prepared, Mathrengyl imparts the final rites necessary to shift into the graceful form of the cat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98397-b3c4fdd03376b70263a1/1-0000.mp3", duration = 56.9469388, start = 0},
  },
}
P.transport["quest:986"] = {
  hash = "73c156",
  fullHash = "73c156",
  text = "A Lost Master. A Lost Master tasks an Alliance adventurer with gathering materials to aid in the search for Volcor, a night elf lost in the wilderness of Darkshore. Terenthis in Auberdine offers to weave an enchanted camouflage cloak to protect the rescuer, requiring pelts from the coast's fiercest moonstalkers. While tracking threats along the coast of Darkshore, Terenthis in Auberdine becomes concerned for the fate of Volcor and his companion, Grimclaw. Venturing deep into the southern reaches of the region is notoriously dangerous due to aggressive predators and corrupted wildlife. Rather than sending a scout unprotected, Terenthis devises a plan to craft a protective cloak imbued with wild illusions. To weave a cloak capable of confounding Darkshore's beasts, standard hides are insufficient. Terenthis requires fine moonstalker pelts taken specifically from mature moonstalker sires or matriarchs. These formidable great cats prowl the woodlands south of Auberdine near the Wildbend River and extend toward the forested border of Ashenvale. The finished garment uses moonstalker fur and nature enchantments to let the wearer pass unhindered through hostile territory while searching for Volcor. However, Terenthis warns that the illusion is delicate: engaging in strenuous activity or combat breaks the enchantment, leaving the searcher exposed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_986-d1106759ee08534312ab/1-0000.mp3", duration = 76.4081633, start = 0},
  },
}
P.transport["quest:993"] = {
  hash = "4d3021",
  fullHash = "4d3021",
  text = "A Lost Master. Having gathered fine moonstalker pelts, you carry the completed Enchanted Moonstalker Cloak into the wilds of Darkshore to find the missing night elf, Volcor. Guided by his loyal white bear Grimclaw, you must track down the wounded scout before hostile furbolgs finish him off. After Terenthis in Auberdine weaves the Enchanted Moonstalker Cloak, the search for the missing scout Volcor begins in earnest. His bear companion, Grimclaw, has returned to the road south of the settlement, standing watch for any ally sent by Terenthis. By offering a familiar greeting to the loyal beast, travelers are led directly off the beaten track toward the cave where Volcor lies in hiding.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_993-6a73ae6ef1d97d99e231/1-0000.mp3", duration = 40.0979592, start = 0},
  },
}
P.transport["quest:995"] = {
  hash = "00ea60",
  fullHash = "00ea60",
  text = "Escape Through Stealth. Escape Through Stealth is an Alliance escort quest set in Darkshore. After locating the trapped night elf scout Volcor deep within a furbolg den, the player helps guide him safely past hostile beasts to freedom before reporting back to Terenthis in Auberdine. Volcor, an operative sent into the depths of Darkshore to investigate the region's mounting threats, ended up cornered inside a furbolg cave. Outnumbered and cut off from the main roads, he relies on a passing ally to coordinate an exit before the hostile furbolgs realize he is slipping away. Rather than attempting a suicidal frontal charge, Volcor chooses caution. Relying on shadows and deliberate maneuvering, he slips past the corrupted denizens of the cavern. Knowing that speed and quiet are paramount, Volcor separates from his rescuer once outside the mouth of the cave, racing ahead on foot while instructing his savior to meet him at the settlement of Auberdine. Upon returning to Auberdine, the player delivers news of the rescue to Terenthis, a night elf leader coordinating efforts to protect the troubled coastline. Terenthis views Volcor's safe return as proof that the encroaching darkness throughout Darkshore and the wilderness beyond can be resisted with discipline and teamwork.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_995-12f3599e98bc7ce99ccb/1-0000.mp3", duration = 72.8555102, start = 0},
  },
}
